export const questions: Question[] = [
  { id: "y2in3-001", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 01", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\sin^2 x \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["trig", "half-angle"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\sin^{2}\\theta = \\frac{1 - \\cos 2\\theta}{2}", explanation: "Half-angle (power-reduction) identity. Rearranges \\(\\cos 2\\theta = 1 - 2\\sin^2\\theta\\) — the form that lets us integrate \\(\\sin^2\\), which has no elementary antiderivative on its own." }, { stepNumber: 2, description: "Why we need the identity in the first place.", workingLatex: "\\sin^2 x \\text{ has no elementary antiderivative as written.}", explanation: "The standard list (power, exp, sin, cos, sec², ...) does not include \\(\\sin^2 x\\). We must convert it first into a sum of standard pieces, which the half-angle identity provides." }, { stepNumber: 3, description: "Apply the identity to rewrite the integrand.", workingLatex: "\\sin^2 x = \\frac{1 - \\cos 2x}{2}", explanation: "Direct substitution with \\(\\theta = x\\). The right-hand side is a sum of a constant and a \\(\\cos\\)-of-linear-inner-argument — both standard." }, { stepNumber: 4, description: "Split the integral term-by-term using linearity.", workingLatex: "\\displaystyle\\int \\frac{1 - \\cos 2x}{2}\\,dx = \\frac{1}{2}\\displaystyle\\int 1\\,dx - \\frac{1}{2}\\displaystyle\\int \\cos 2x\\,dx", explanation: "Constant \\(\\frac{1}{2}\\) factors out; the sum-of-integrals splits into two." }, { stepNumber: 5, description: "Integrate each piece using its standard antiderivative.", workingLatex: "\\frac{1}{2}\\displaystyle\\int 1\\,dx = \\frac{x}{2}; \\qquad \\frac{1}{2}\\displaystyle\\int \\cos 2x\\,dx = \\frac{1}{2} \\cdot \\frac{\\sin 2x}{2} = \\frac{\\sin 2x}{4}", explanation: "\\(\\int 1\\,dx = x\\); \\(\\int \\cos 2x\\,dx = \\sin 2x/2\\) by the linear-inner-argument cosine rule with \\(a = 2\\)." }, { stepNumber: 6, description: "Combine and finish.", workingLatex: "\\displaystyle\\int \\sin^2 x\\,dx = \\frac{x}{2} - \\frac{\\sin 2x}{4} + C", explanation: "Differentiation check: \\(\\frac{d}{dx}\\!\\left[\\frac{x}{2} - \\frac{\\sin 2x}{4}\\right] = \\frac{1}{2} - \\frac{2\\cos 2x}{4} = \\frac{1 - \\cos 2x}{2} = \\sin^2 x\\) ✓." } ], finalAnswer: "\\(\\frac{x}{2} - \\frac{\\sin 2x}{4} + C\\)." } },
  { id: "y2in3-002", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 02", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\cos^2 x \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["trig", "half-angle"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\cos^{2}\\theta = \\frac{1 + \\cos 2\\theta}{2}", explanation: "Half-angle identity for cosine. Rearranges \\(\\cos 2\\theta = 2\\cos^2\\theta - 1\\)." }, { stepNumber: 2, description: "Why the identity is needed.", workingLatex: "\\cos^2 x \\text{ has no elementary antiderivative as written.}", explanation: "Same reason as for \\(\\sin^2 x\\): we need to convert to a sum of standard antiderivatives." }, { stepNumber: 3, description: "Apply the identity.", workingLatex: "\\cos^2 x = \\frac{1 + \\cos 2x}{2}", explanation: "Note the \\(+\\) (unlike sin²). The constant + cosine form is what we want." }, { stepNumber: 4, description: "Split into two integrals.", workingLatex: "\\displaystyle\\int \\frac{1 + \\cos 2x}{2}\\,dx = \\frac{1}{2}\\displaystyle\\int 1\\,dx + \\frac{1}{2}\\displaystyle\\int \\cos 2x\\,dx", explanation: "" }, { stepNumber: 5, description: "Integrate each piece.", workingLatex: "= \\frac{x}{2} + \\frac{1}{2} \\cdot \\frac{\\sin 2x}{2} + C = \\frac{x}{2} + \\frac{\\sin 2x}{4} + C", explanation: "\\(\\int \\cos 2x\\,dx = \\sin 2x/2\\)." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\frac{d}{dx}\\!\\left[\\frac{x}{2} + \\frac{\\sin 2x}{4}\\right] = \\frac{1}{2} + \\frac{\\cos 2x}{2} = \\frac{1 + \\cos 2x}{2} = \\cos^2 x \\;\\checkmark", explanation: "" } ], finalAnswer: "\\(\\frac{x}{2} + \\frac{\\sin 2x}{4} + C\\)." } },
  { id: "y2in3-003", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 03", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\sin^2\\left(2x\\right) \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["trig", "half-angle"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\sin^{2}\\theta = \\frac{1 - \\cos 2\\theta}{2}", explanation: "Half-angle (power-reduction) identity. Rearranges \\(\\cos 2\\theta = 1 - 2\\sin^2\\theta\\) — the form that lets us integrate \\(\\sin^2\\), which has no elementary antiderivative on its own." }, { stepNumber: 2, description: "Apply the half-angle identity with \\(\\theta = 2x\\).", workingLatex: "\\sin^2\\left(2x\\right) = \\frac{1 - \\cos\\left(2 \\cdot 2x\\right)}{2} = \\frac{1 - \\cos 4x}{2}", explanation: "\\(\\theta = 2x\\) gives \\(2\\theta = 4x\\) — the cosine argument doubles to \\(4x\\)." }, { stepNumber: 3, description: "Split the integral.", workingLatex: "\\displaystyle\\int \\frac{1 - \\cos 4x}{2}\\,dx = \\frac{1}{2}\\displaystyle\\int 1\\,dx - \\frac{1}{2}\\displaystyle\\int \\cos 4x\\,dx", explanation: "" }, { stepNumber: 4, description: "Apply the cosine rule with \\(a = 4\\).", workingLatex: "\\displaystyle\\int \\cos 4x\\,dx = \\frac{\\sin 4x}{4}", explanation: "Divide by the inner coefficient \\(a = 4\\)." }, { stepNumber: 5, description: "Combine and tidy.", workingLatex: "\\displaystyle\\int \\sin^2\\left(2x\\right)\\,dx = \\frac{x}{2} - \\frac{1}{2} \\cdot \\frac{\\sin 4x}{4} + C = \\frac{x}{2} - \\frac{\\sin 4x}{8} + C", explanation: "" } ], finalAnswer: "\\(\\frac{x}{2} - \\frac{\\sin 4x}{8} + C\\)." } },
  { id: "y2in3-004", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 04", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\cos^2\\left(3x\\right) \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["trig", "half-angle"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\cos^{2}\\theta = \\frac{1 + \\cos 2\\theta}{2}", explanation: "Half-angle identity for cosine. Rearranges \\(\\cos 2\\theta = 2\\cos^2\\theta - 1\\)." }, { stepNumber: 2, description: "Apply the half-angle identity with \\(\\theta = 3x\\).", workingLatex: "\\cos^2\\left(3x\\right) = \\frac{1 + \\cos 6x}{2}", explanation: "\\(2\\theta = 6x\\) inside the cosine." }, { stepNumber: 3, description: "Split into two integrals.", workingLatex: "\\displaystyle\\int \\frac{1 + \\cos 6x}{2}\\,dx = \\frac{1}{2}\\displaystyle\\int 1\\,dx + \\frac{1}{2}\\displaystyle\\int \\cos 6x\\,dx", explanation: "" }, { stepNumber: 4, description: "Integrate \\(\\cos 6x\\) using the linear-inner rule (\\(a = 6\\)).", workingLatex: "\\frac{1}{2}\\displaystyle\\int \\cos 6x\\,dx = \\frac{1}{2} \\cdot \\frac{\\sin 6x}{6} = \\frac{\\sin 6x}{12}", explanation: "" }, { stepNumber: 5, description: "Combine.", workingLatex: "\\displaystyle\\int \\cos^2\\left(3x\\right)\\,dx = \\frac{x}{2} + \\frac{\\sin 6x}{12} + C", explanation: "" } ], finalAnswer: "\\(\\frac{x}{2} + \\frac{\\sin 6x}{12} + C\\)." } },
  { id: "y2in3-005", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 05", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\sin^2\\left(\\frac{x}{2}\\right) \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["trig", "half-angle"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\sin^{2}\\theta = \\frac{1 - \\cos 2\\theta}{2}", explanation: "Half-angle (power-reduction) identity. Rearranges \\(\\cos 2\\theta = 1 - 2\\sin^2\\theta\\) — the form that lets us integrate \\(\\sin^2\\), which has no elementary antiderivative on its own." }, { stepNumber: 2, description: "Apply the half-angle identity with \\(\\theta = x/2\\).", workingLatex: "\\sin^2\\!\\left(\\frac{x}{2}\\right) = \\frac{1 - \\cos x}{2}", explanation: "\\(2\\theta = 2 \\cdot \\frac{x}{2} = x\\) — the halving and the doubling cancel, so the cosine argument becomes \\(x\\), not \\(x/2\\) or \\(2x\\)." }, { stepNumber: 3, description: "Split the integral.", workingLatex: "\\displaystyle\\int \\frac{1 - \\cos x}{2}\\,dx = \\frac{1}{2}\\displaystyle\\int 1\\,dx - \\frac{1}{2}\\displaystyle\\int \\cos x\\,dx", explanation: "" }, { stepNumber: 4, description: "Apply the cosine rule (\\(a = 1\\), so no division).", workingLatex: "= \\frac{x}{2} - \\frac{\\sin x}{2} + C", explanation: "" } ], finalAnswer: "\\(\\frac{x}{2} - \\frac{\\sin x}{2} + C\\)." } },
  { id: "y2in3-006", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 06", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\tan^2 x \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig", "pythag"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\tan^{2}\\theta = \\sec^{2}\\theta - 1", explanation: "Pythagorean identity: divide \\(\\sin^2\\theta + \\cos^2\\theta = 1\\) through by \\(\\cos^2\\theta\\). Lets us turn \\(\\tan^2\\) into the standard \\(\\sec^2\\) antiderivative." }, { stepNumber: 2, description: "Why the identity is needed.", workingLatex: "\\tan^2 x \\text{ has no elementary antiderivative as written.}", explanation: "But \\(\\sec^2 x\\) does — \\(\\int \\sec^2 x\\,dx = \\tan x\\). Convert." }, { stepNumber: 3, description: "Apply the identity.", workingLatex: "\\tan^2 x = \\sec^2 x - 1", explanation: "Direct rearrangement of the Pythagorean identity (divide \\(\\sin^2 + \\cos^2 = 1\\) by \\(\\cos^2\\))." }, { stepNumber: 4, description: "Split the integral.", workingLatex: "\\displaystyle\\int \\left(\\sec^2 x - 1\\right)\\,dx = \\displaystyle\\int \\sec^2 x\\,dx - \\displaystyle\\int 1\\,dx", explanation: "" }, { stepNumber: 5, description: "Integrate each piece.", workingLatex: "= \\tan x - x + C", explanation: "" } ], finalAnswer: "\\(\\tan x - x + C\\)." } },
  { id: "y2in3-007", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 07", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\tan^2\\left(2x\\right) \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig", "pythag"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\tan^{2}\\theta = \\sec^{2}\\theta - 1", explanation: "Pythagorean identity: divide \\(\\sin^2\\theta + \\cos^2\\theta = 1\\) through by \\(\\cos^2\\theta\\). Lets us turn \\(\\tan^2\\) into the standard \\(\\sec^2\\) antiderivative." }, { stepNumber: 2, description: "Apply the identity with \\(\\theta = 2x\\).", workingLatex: "\\tan^2\\left(2x\\right) = \\sec^2\\left(2x\\right) - 1", explanation: "" }, { stepNumber: 3, description: "Split the integral.", workingLatex: "\\displaystyle\\int \\left(\\sec^2\\left(2x\\right) - 1\\right)\\,dx = \\displaystyle\\int \\sec^2\\left(2x\\right)\\,dx - \\displaystyle\\int 1\\,dx", explanation: "" }, { stepNumber: 4, description: "Apply the linear-inner \\(\\sec^2\\) rule with \\(a = 2\\).", workingLatex: "\\displaystyle\\int \\sec^2\\left(2x\\right)\\,dx = \\frac{\\tan 2x}{2}", explanation: "" }, { stepNumber: 5, description: "Combine.", workingLatex: "\\displaystyle\\int \\tan^2\\left(2x\\right)\\,dx = \\frac{\\tan 2x}{2} - x + C", explanation: "" } ], finalAnswer: "\\(\\frac{\\tan 2x}{2} - x + C\\)." } },
  { id: "y2in3-008", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 08", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\cot^2 x \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig", "pythag"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\cot^{2}\\theta = \\csc^{2}\\theta - 1", explanation: "Pythagorean identity: divide through by \\(\\sin^2\\theta\\). Lets us turn \\(\\cot^2\\) into the standard \\(\\csc^2\\) antiderivative." }, { stepNumber: 2, description: "Apply the identity.", workingLatex: "\\cot^2 x = \\csc^2 x - 1", explanation: "Pythagorean identity divided by \\(\\sin^2 x\\)." }, { stepNumber: 3, description: "Split the integral.", workingLatex: "\\displaystyle\\int \\left(\\csc^2 x - 1\\right)\\,dx = \\displaystyle\\int \\csc^2 x\\,dx - \\displaystyle\\int 1\\,dx", explanation: "" }, { stepNumber: 4, description: "Integrate each piece.", workingLatex: "= -\\cot x - x + C", explanation: "\\(\\int \\csc^2 x\\,dx = -\\cot x\\); mind the minus sign — it comes from \\(\\frac{d}{dx}\\cot x = -\\csc^2 x\\)." } ], finalAnswer: "\\(-\\cot x - x + C\\)." } },
  { id: "y2in3-009", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 09", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\sin x\\cos x \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig", "double-angle"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "2\\sin\\theta\\cos\\theta = \\sin 2\\theta", explanation: "Double-angle identity. Halves the work when integrating a \\(\\sin\\cos\\) product — converts to a single \\(\\sin\\) of doubled argument." }, { stepNumber: 2, description: "Rewrite the product using the double-angle identity.", workingLatex: "\\sin x\\cos x = \\frac{1}{2}\\left(2\\sin x\\cos x\\right) = \\frac{\\sin 2x}{2}", explanation: "Direct application of \\(2\\sin\\cos = \\sin 2\\theta\\), halved." }, { stepNumber: 3, description: "Set up the integral.", workingLatex: "\\displaystyle\\int \\sin x\\cos x\\,dx = \\frac{1}{2}\\displaystyle\\int \\sin 2x\\,dx", explanation: "" }, { stepNumber: 4, description: "Apply the linear-inner sine rule (\\(a = 2\\)).", workingLatex: "= \\frac{1}{2} \\cdot \\left(-\\frac{\\cos 2x}{2}\\right) + C = -\\frac{\\cos 2x}{4} + C", explanation: "" } ], finalAnswer: "\\(-\\frac{\\cos 2x}{4} + C\\)." } },
  { id: "y2in3-010", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 10", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\sin\\left(3x\\right)\\cos\\left(3x\\right) \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig", "double-angle"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "2\\sin\\theta\\cos\\theta = \\sin 2\\theta", explanation: "Double-angle identity. Halves the work when integrating a \\(\\sin\\cos\\) product — converts to a single \\(\\sin\\) of doubled argument." }, { stepNumber: 2, description: "Apply the double-angle identity with \\(\\theta = 3x\\).", workingLatex: "\\sin 3x\\cos 3x = \\frac{\\sin 6x}{2}", explanation: "\\(2 \\cdot 3x = 6x\\)." }, { stepNumber: 3, description: "Set up the integral.", workingLatex: "\\displaystyle\\int \\sin 3x\\cos 3x\\,dx = \\frac{1}{2}\\displaystyle\\int \\sin 6x\\,dx", explanation: "" }, { stepNumber: 4, description: "Apply the sine rule (\\(a = 6\\)).", workingLatex: "= \\frac{1}{2} \\cdot \\left(-\\frac{\\cos 6x}{6}\\right) + C = -\\frac{\\cos 6x}{12} + C", explanation: "" } ], finalAnswer: "\\(-\\frac{\\cos 6x}{12} + C\\)." } },
  { id: "y2in3-011", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 11", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\sin\\left(5x\\right)\\cos\\left(3x\\right) \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["trig", "product-to-sum"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\sin A\\cos B = \\frac{1}{2}[\\sin\\left(A+B\\right) + \\sin\\left(A-B\\right)]", explanation: "Product-to-sum identity. Converts a product of \\(\\sin\\) and \\(\\cos\\) (at different multiples of \\(x\\)) into a sum of single sines, each of which integrates directly." }, { stepNumber: 2, description: "Apply product-to-sum with \\(A = 5x\\), \\(B = 3x\\).", workingLatex: "\\sin 5x\\cos 3x = \\frac{1}{2}\\!\\left[\\sin\\left(5x + 3x\\right) + \\sin\\left(5x - 3x\\right)\\right]", explanation: "Always do this conversion before integrating a product of sin/cos at different multiples — otherwise you cannot integrate by inspection." }, { stepNumber: 3, description: "Simplify the arguments.", workingLatex: "= \\frac{1}{2}\\!\\left[\\sin 8x + \\sin 2x\\right]", explanation: "\\(A + B = 8x\\); \\(A - B = 2x\\)." }, { stepNumber: 4, description: "Set up the integral.", workingLatex: "\\displaystyle\\int \\sin 5x\\cos 3x\\,dx = \\frac{1}{2}\\displaystyle\\int \\sin 8x\\,dx + \\frac{1}{2}\\displaystyle\\int \\sin 2x\\,dx", explanation: "" }, { stepNumber: 5, description: "Integrate each piece using the sine rule.", workingLatex: "= \\frac{1}{2} \\cdot \\left(-\\frac{\\cos 8x}{8}\\right) + \\frac{1}{2} \\cdot \\left(-\\frac{\\cos 2x}{2}\\right) + C", explanation: "" }, { stepNumber: 6, description: "Tidy.", workingLatex: "= -\\frac{\\cos 8x}{16} - \\frac{\\cos 2x}{4} + C", explanation: "" } ], finalAnswer: "\\(-\\frac{\\cos 8x}{16} - \\frac{\\cos 2x}{4} + C\\)." } },
  { id: "y2in3-012", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 12", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\cos\\left(2x\\right)\\cos\\left(3x\\right) \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["trig", "product-to-sum"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\cos A\\cos B = \\frac{1}{2}[\\cos\\left(A-B\\right) + \\cos\\left(A+B\\right)]", explanation: "Product-to-sum identity for two cosines." }, { stepNumber: 2, description: "Apply product-to-sum with \\(A = 2x\\), \\(B = 3x\\).", workingLatex: "\\cos 2x\\cos 3x = \\frac{1}{2}\\!\\left[\\cos\\left(2x - 3x\\right) + \\cos\\left(2x + 3x\\right)\\right]", explanation: "" }, { stepNumber: 3, description: "Simplify using \\(\\cos(-x) = \\cos x\\).", workingLatex: "= \\frac{1}{2}\\!\\left[\\cos\\left(-x\\right) + \\cos 5x\\right] = \\frac{1}{2}\\!\\left[\\cos x + \\cos 5x\\right]", explanation: "Cosine is even — the negative inside disappears." }, { stepNumber: 4, description: "Set up the integral.", workingLatex: "\\displaystyle\\int \\cos 2x\\cos 3x\\,dx = \\frac{1}{2}\\displaystyle\\int \\cos x\\,dx + \\frac{1}{2}\\displaystyle\\int \\cos 5x\\,dx", explanation: "" }, { stepNumber: 5, description: "Integrate each piece.", workingLatex: "= \\frac{\\sin x}{2} + \\frac{\\sin 5x}{10} + C", explanation: "\\(\\int \\cos x\\,dx = \\sin x\\); \\(\\int \\cos 5x\\,dx = \\sin 5x/5\\)." } ], finalAnswer: "\\(\\frac{\\sin 5x}{10} + \\frac{\\sin x}{2} + C\\)." } },
  { id: "y2in3-013", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 13", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\sin\\left(4x\\right)\\sin\\left(2x\\right) \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["trig", "product-to-sum"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\sin A\\sin B = \\frac{1}{2}[\\cos\\left(A-B\\right) - \\cos\\left(A+B\\right)]", explanation: "Product-to-sum identity for two sines. Note the minus sign on the second term." }, { stepNumber: 2, description: "Apply product-to-sum with \\(A = 4x\\), \\(B = 2x\\).", workingLatex: "\\sin 4x\\sin 2x = \\frac{1}{2}\\!\\left[\\cos\\left(4x - 2x\\right) - \\cos\\left(4x + 2x\\right)\\right] = \\frac{1}{2}\\!\\left[\\cos 2x - \\cos 6x\\right]", explanation: "Note the MINUS between the cosines — that\\'s the distinguishing feature of \\(\\sin\\sin\\) versus \\(\\cos\\cos\\)." }, { stepNumber: 3, description: "Set up the integral.", workingLatex: "\\displaystyle\\int \\sin 4x\\sin 2x\\,dx = \\frac{1}{2}\\displaystyle\\int \\cos 2x\\,dx - \\frac{1}{2}\\displaystyle\\int \\cos 6x\\,dx", explanation: "" }, { stepNumber: 4, description: "Integrate each piece.", workingLatex: "= \\frac{1}{2} \\cdot \\frac{\\sin 2x}{2} - \\frac{1}{2} \\cdot \\frac{\\sin 6x}{6} + C", explanation: "" }, { stepNumber: 5, description: "Tidy.", workingLatex: "= \\frac{\\sin 2x}{4} - \\frac{\\sin 6x}{12} + C", explanation: "" } ], finalAnswer: "\\(\\frac{\\sin 2x}{4} - \\frac{\\sin 6x}{12} + C\\)." } },
  { id: "y2in3-014", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 14", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\sin^2 x\\cos x \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["trig", "u-substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\text{If } u = g(x),\\;\\; du = g\\'(x)\\,dx \\;\\Rightarrow\\; \\displaystyle\\int f(g(x))\\,g\\'(x)\\,dx = \\displaystyle\\int f(u)\\,du", explanation: "Reverse-chain-rule (substitution). Used here whenever the integrand contains a function and its derivative as a factor — pick the inner part as \\(u\\)." }, { stepNumber: 2, description: "Spot the function-and-its-derivative pattern.", workingLatex: "\\frac{d}{dx}\\sin x = \\cos x", explanation: "\\(\\sin^2 x\\) is a function of \\(\\sin x\\); the rest of the integrand is exactly the derivative of \\(\\sin x\\). This is the canonical setup for substitution." }, { stepNumber: 3, description: "Choose the substitution.", workingLatex: "u = \\sin x \\;\\Rightarrow\\; \\frac{du}{dx} = \\cos x \\;\\Rightarrow\\; du = \\cos x\\,dx", explanation: "" }, { stepNumber: 4, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int \\sin^2 x\\cos x\\,dx = \\displaystyle\\int u^2\\,du", explanation: "\\(\\sin^2 x = u^2\\); \\(\\cos x\\,dx = du\\)." }, { stepNumber: 5, description: "Integrate in \\(u\\) using the power rule.", workingLatex: "\\displaystyle\\int u^2\\,du = \\frac{u^3}{3} + C", explanation: "" }, { stepNumber: 6, description: "Back-substitute \\(u = \\sin x\\).", workingLatex: "= \\frac{\\sin^3 x}{3} + C", explanation: "Differentiation check: \\(\\frac{d}{dx}\\!\\left[\\frac{\\sin^3 x}{3}\\right] = \\frac{3\\sin^2 x \\cdot \\cos x}{3} = \\sin^2 x\\cos x\\) ✓." } ], finalAnswer: "\\(\\frac{\\sin^3 x}{3} + C\\)." } },
  { id: "y2in3-015", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 15", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\cos^2 x\\sin x \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["trig", "u-substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\text{If } u = g(x),\\;\\; du = g\\'(x)\\,dx \\;\\Rightarrow\\; \\displaystyle\\int f(g(x))\\,g\\'(x)\\,dx = \\displaystyle\\int f(u)\\,du", explanation: "Reverse-chain-rule (substitution). Used here whenever the integrand contains a function and its derivative as a factor — pick the inner part as \\(u\\)." }, { stepNumber: 2, description: "Choose \\(u = \\cos x\\) since its derivative is \\(-\\sin x\\).", workingLatex: "u = \\cos x \\;\\Rightarrow\\; du = -\\sin x\\,dx \\;\\Rightarrow\\; \\sin x\\,dx = -du", explanation: "The factor \\(\\sin x\\) in the integrand is the negative derivative of \\(\\cos x\\), so we pick up a minus when converting." }, { stepNumber: 3, description: "Rewrite the integral.", workingLatex: "\\displaystyle\\int \\cos^2 x\\sin x\\,dx = \\displaystyle\\int u^2 \\cdot \\left(-du\\right) = -\\displaystyle\\int u^2\\,du", explanation: "" }, { stepNumber: 4, description: "Integrate.", workingLatex: "-\\displaystyle\\int u^2\\,du = -\\frac{u^3}{3} + C", explanation: "" }, { stepNumber: 5, description: "Back-substitute.", workingLatex: "= -\\frac{\\cos^3 x}{3} + C", explanation: "" } ], finalAnswer: "\\(-\\frac{\\cos^3 x}{3} + C\\)." } },
  { id: "y2in3-016", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 16", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\sin^3 x \\,dx \\).", marks: 4, examStyle: false, yearCreated: 2026, tags: ["trig", "pythag", "u-substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identities used.", workingLatex: "\\sin^{2}\\theta + \\cos^{2}\\theta = 1 \\\\\\\\[2pt] \\text{If } u = g(x),\\;\\; du = g\\'(x)\\,dx \\;\\Rightarrow\\; \\displaystyle\\int f(g(x))\\,g\\'(x)\\,dx = \\displaystyle\\int f(u)\\,du", explanation: "The Pythagorean identity. Used to split \\(\\sin^3 = \\sin\\left(1-\\cos^2\\right)\\) or \\(\\cos^3 = \\cos\\left(1-\\sin^2\\right)\\) into pieces that admit a substitution.  Reverse-chain-rule (substitution). Used here whenever the integrand contains a function and its derivative as a factor — pick the inner part as \\(u\\)." }, { stepNumber: 2, description: "Odd-power strategy: split off one \\(\\sin x\\).", workingLatex: "\\sin^3 x = \\sin x \\cdot \\sin^2 x", explanation: "For odd powers of sin or cos, peel off one factor (so it can become \\(du\\)) and apply Pythagoras to convert the rest into the other trig function." }, { stepNumber: 3, description: "Apply Pythagoras to the leftover \\(\\sin^2 x\\).", workingLatex: "\\sin^2 x = 1 - \\cos^2 x \\;\\Rightarrow\\; \\sin^3 x = \\sin x\\,\\left(1 - \\cos^2 x\\right)", explanation: "" }, { stepNumber: 4, description: "Choose \\(u = \\cos x\\) so that \\(\\sin x\\,dx = -du\\).", workingLatex: "u = \\cos x, \\;\\; du = -\\sin x\\,dx", explanation: "" }, { stepNumber: 5, description: "Convert the integral.", workingLatex: "\\displaystyle\\int \\sin x\\,\\left(1 - \\cos^2 x\\right)\\,dx = \\displaystyle\\int \\left(1 - u^2\\right)\\,\\left(-du\\right) = -\\displaystyle\\int \\left(1 - u^2\\right)\\,du", explanation: "" }, { stepNumber: 6, description: "Integrate in \\(u\\).", workingLatex: "-\\displaystyle\\int \\left(1 - u^2\\right)\\,du = -u + \\frac{u^3}{3} + C", explanation: "" }, { stepNumber: 7, description: "Back-substitute.", workingLatex: "= -\\cos x + \\frac{\\cos^3 x}{3} + C", explanation: "" } ], finalAnswer: "\\(-\\cos x + \\frac{\\cos^3 x}{3} + C\\)." } },
  { id: "y2in3-017", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 17", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\cos^3 x \\,dx \\).", marks: 4, examStyle: false, yearCreated: 2026, tags: ["trig", "pythag", "u-substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identities used.", workingLatex: "\\sin^{2}\\theta + \\cos^{2}\\theta = 1 \\\\\\\\[2pt] \\text{If } u = g(x),\\;\\; du = g\\'(x)\\,dx \\;\\Rightarrow\\; \\displaystyle\\int f(g(x))\\,g\\'(x)\\,dx = \\displaystyle\\int f(u)\\,du", explanation: "The Pythagorean identity. Used to split \\(\\sin^3 = \\sin\\left(1-\\cos^2\\right)\\) or \\(\\cos^3 = \\cos\\left(1-\\sin^2\\right)\\) into pieces that admit a substitution.  Reverse-chain-rule (substitution). Used here whenever the integrand contains a function and its derivative as a factor — pick the inner part as \\(u\\)." }, { stepNumber: 2, description: "Split off one \\(\\cos x\\).", workingLatex: "\\cos^3 x = \\cos x \\cdot \\cos^2 x", explanation: "" }, { stepNumber: 3, description: "Apply Pythagoras to the leftover \\(\\cos^2 x\\).", workingLatex: "\\cos^2 x = 1 - \\sin^2 x \\;\\Rightarrow\\; \\cos^3 x = \\cos x\\,\\left(1 - \\sin^2 x\\right)", explanation: "" }, { stepNumber: 4, description: "Choose \\(u = \\sin x\\) so that \\(\\cos x\\,dx = du\\).", workingLatex: "u = \\sin x, \\;\\; du = \\cos x\\,dx", explanation: "" }, { stepNumber: 5, description: "Convert and integrate.", workingLatex: "\\displaystyle\\int \\cos x\\,\\left(1 - \\sin^2 x\\right)\\,dx = \\displaystyle\\int \\left(1 - u^2\\right)\\,du = u - \\frac{u^3}{3} + C", explanation: "" }, { stepNumber: 6, description: "Back-substitute.", workingLatex: "= \\sin x - \\frac{\\sin^3 x}{3} + C", explanation: "" } ], finalAnswer: "\\(\\sin x - \\frac{\\sin^3 x}{3} + C\\)." } },
  { id: "y2in3-018", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 18", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\sin^4 x \\,dx \\).", marks: 5, examStyle: false, yearCreated: 2026, tags: ["trig", "half-angle"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identities used.", workingLatex: "\\sin^{2}\\theta = \\frac{1 - \\cos 2\\theta}{2} \\\\\\\\[2pt] \\cos^{2}\\theta = \\frac{1 + \\cos 2\\theta}{2}", explanation: "Half-angle (power-reduction) identity. Rearranges \\(\\cos 2\\theta = 1 - 2\\sin^2\\theta\\) — the form that lets us integrate \\(\\sin^2\\), which has no elementary antiderivative on its own.  Half-angle identity for cosine. Rearranges \\(\\cos 2\\theta = 2\\cos^2\\theta - 1\\)." }, { stepNumber: 2, description: "Even-power strategy: apply the half-angle identity once for each pair.", workingLatex: "\\sin^4 x = \\left(\\sin^2 x\\right)^2", explanation: "For even powers of sin/cos, repeated half-angle gets us down to a sum of standard pieces. No substitution needed." }, { stepNumber: 3, description: "Apply the half-angle identity to \\(\\sin^2 x\\).", workingLatex: "\\sin^4 x = \\left(\\frac{1 - \\cos 2x}{2}\\right)^{\\!2} = \\frac{\\left(1 - \\cos 2x\\right)^2}{4} = \\frac{1 - 2\\cos 2x + \\cos^2 2x}{4}", explanation: "Expand the square: \\(\\left(a - b\\right)^2 = a^2 - 2ab + b^2\\) with \\(a = 1\\), \\(b = \\cos 2x\\)." }, { stepNumber: 4, description: "Apply the half-angle identity AGAIN to \\(\\cos^2 2x\\).", workingLatex: "\\cos^2 2x = \\frac{1 + \\cos 4x}{2}", explanation: "" }, { stepNumber: 5, description: "Combine into a single fraction.", workingLatex: "\\sin^4 x = \\frac{1 - 2\\cos 2x + \\frac{1 + \\cos 4x}{2}}{4} = \\frac{2 - 4\\cos 2x + 1 + \\cos 4x}{8} = \\frac{3 - 4\\cos 2x + \\cos 4x}{8}", explanation: "Common denominator \\(2\\) in the numerator, then divide by an extra \\(4\\) — overall denominator \\(8\\)." }, { stepNumber: 6, description: "Split the integral and integrate term-by-term.", workingLatex: "\\displaystyle\\int \\sin^4 x\\,dx = \\frac{1}{8}\\!\\left[\\displaystyle\\int 3\\,dx - 4\\displaystyle\\int \\cos 2x\\,dx + \\displaystyle\\int \\cos 4x\\,dx\\right]", explanation: "" }, { stepNumber: 7, description: "Apply the cosine rule to each piece.", workingLatex: "= \\frac{1}{8}\\!\\left[3x - 4 \\cdot \\frac{\\sin 2x}{2} + \\frac{\\sin 4x}{4}\\right] + C", explanation: "" }, { stepNumber: 8, description: "Tidy.", workingLatex: "= \\frac{3x}{8} - \\frac{\\sin 2x}{4} + \\frac{\\sin 4x}{32} + C", explanation: "" } ], finalAnswer: "\\(\\frac{3x}{8} - \\frac{\\sin 2x}{4} + \\frac{\\sin 4x}{32} + C\\)." } },
  { id: "y2in3-019", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 19", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\cos^4 x \\,dx \\).", marks: 5, examStyle: false, yearCreated: 2026, tags: ["trig", "half-angle"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\cos^{2}\\theta = \\frac{1 + \\cos 2\\theta}{2}", explanation: "Half-angle identity for cosine. Rearranges \\(\\cos 2\\theta = 2\\cos^2\\theta - 1\\)." }, { stepNumber: 2, description: "Even-power strategy: repeated half-angle.", workingLatex: "\\cos^4 x = \\left(\\cos^2 x\\right)^2", explanation: "" }, { stepNumber: 3, description: "Apply the half-angle identity and expand the square.", workingLatex: "\\cos^4 x = \\left(\\frac{1 + \\cos 2x}{2}\\right)^{\\!2} = \\frac{1 + 2\\cos 2x + \\cos^2 2x}{4}", explanation: "\\(\\left(a + b\\right)^2 = a^2 + 2ab + b^2\\) — all PLUS this time." }, { stepNumber: 4, description: "Apply the half-angle identity to \\(\\cos^2 2x\\).", workingLatex: "\\cos^2 2x = \\frac{1 + \\cos 4x}{2}", explanation: "" }, { stepNumber: 5, description: "Combine.", workingLatex: "\\cos^4 x = \\frac{3 + 4\\cos 2x + \\cos 4x}{8}", explanation: "" }, { stepNumber: 6, description: "Integrate term-by-term.", workingLatex: "\\displaystyle\\int \\cos^4 x\\,dx = \\frac{1}{8}\\!\\left[3x + 4 \\cdot \\frac{\\sin 2x}{2} + \\frac{\\sin 4x}{4}\\right] + C = \\frac{3x}{8} + \\frac{\\sin 2x}{4} + \\frac{\\sin 4x}{32} + C", explanation: "" } ], finalAnswer: "\\(\\frac{3x}{8} + \\frac{\\sin 2x}{4} + \\frac{\\sin 4x}{32} + C\\)." } },
  { id: "y2in3-020", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 20", difficulty: "Foundation", questionText: "Find \\( \\displaystyle\\int \\left(1 - \\sin^2 x\\right) \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig", "pythag"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\sin^{2}\\theta + \\cos^{2}\\theta = 1", explanation: "The Pythagorean identity. Used to split \\(\\sin^3 = \\sin\\left(1-\\cos^2\\right)\\) or \\(\\cos^3 = \\cos\\left(1-\\sin^2\\right)\\) into pieces that admit a substitution." }, { stepNumber: 2, description: "Recognise the integrand using Pythagoras.", workingLatex: "\\sin^2 x + \\cos^2 x = 1 \\;\\Rightarrow\\; 1 - \\sin^2 x = \\cos^2 x", explanation: "The trick is to simplify FIRST — never integrate \\(1 - \\sin^2 x\\) as a sum." }, { stepNumber: 3, description: "Use the half-angle identity on the simplified form.", workingLatex: "\\cos^2 x = \\frac{1 + \\cos 2x}{2}", explanation: "See Q002 for the full integration." }, { stepNumber: 4, description: "Integrate term-by-term.", workingLatex: "\\displaystyle\\int \\cos^2 x\\,dx = \\frac{x}{2} + \\frac{\\sin 2x}{4} + C", explanation: "" } ], finalAnswer: "\\(\\frac{x}{2} + \\frac{\\sin 2x}{4} + C\\)." } },
  { id: "y2in3-021", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 21", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\left(2\\sin^2 x - 1\\right) \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["trig", "double-angle"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\sin^{2}\\theta = \\frac{1 - \\cos 2\\theta}{2}", explanation: "Half-angle (power-reduction) identity. Rearranges \\(\\cos 2\\theta = 1 - 2\\sin^2\\theta\\) — the form that lets us integrate \\(\\sin^2\\), which has no elementary antiderivative on its own." }, { stepNumber: 2, description: "Rearrange the half-angle identity.", workingLatex: "\\sin^2 x = \\frac{1 - \\cos 2x}{2} \\;\\Rightarrow\\; 2\\sin^2 x = 1 - \\cos 2x", explanation: "Multiply through by \\(2\\)." }, { stepNumber: 3, description: "Subtract \\(1\\) to match the integrand.", workingLatex: "2\\sin^2 x - 1 = \\left(1 - \\cos 2x\\right) - 1 = -\\cos 2x", explanation: "The constants cancel; we are left with a single \\(\\cos 2x\\) (with a minus)." }, { stepNumber: 4, description: "Integrate.", workingLatex: "\\displaystyle\\int -\\cos 2x\\,dx = -\\frac{\\sin 2x}{2} + C", explanation: "" } ], finalAnswer: "\\(-\\frac{\\sin 2x}{2} + C\\)." } },
  { id: "y2in3-022", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 22", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\left(\\sin x + \\cos x\\right)^2 \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["trig", "expand", "double-angle"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identities used.", workingLatex: "\\sin^{2}\\theta + \\cos^{2}\\theta = 1 \\\\\\\\[2pt] 2\\sin\\theta\\cos\\theta = \\sin 2\\theta", explanation: "The Pythagorean identity. Used to split \\(\\sin^3 = \\sin\\left(1-\\cos^2\\right)\\) or \\(\\cos^3 = \\cos\\left(1-\\sin^2\\right)\\) into pieces that admit a substitution.  Double-angle identity. Halves the work when integrating a \\(\\sin\\cos\\) product — converts to a single \\(\\sin\\) of doubled argument." }, { stepNumber: 2, description: "Expand the bracket using \\((a+b)^2\\).", workingLatex: "\\left(\\sin x + \\cos x\\right)^2 = \\sin^2 x + 2\\sin x\\cos x + \\cos^2 x", explanation: "" }, { stepNumber: 3, description: "Group like terms and apply the identities.", workingLatex: "= \\left(\\sin^2 x + \\cos^2 x\\right) + 2\\sin x\\cos x = 1 + \\sin 2x", explanation: "Pythagoras collapses the squares to \\(1\\); double-angle collapses the cross-term to \\(\\sin 2x\\)." }, { stepNumber: 4, description: "Split and integrate.", workingLatex: "\\displaystyle\\int \\left(1 + \\sin 2x\\right)\\,dx = \\displaystyle\\int 1\\,dx + \\displaystyle\\int \\sin 2x\\,dx", explanation: "" }, { stepNumber: 5, description: "Apply the standard antiderivatives.", workingLatex: "= x + \\left(-\\frac{\\cos 2x}{2}\\right) + C = x - \\frac{\\cos 2x}{2} + C", explanation: "" } ], finalAnswer: "\\(x - \\frac{\\cos 2x}{2} + C\\)." } },
  { id: "y2in3-023", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 23", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\left(\\sin x - \\cos x\\right)^2 \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["trig", "expand"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identities used.", workingLatex: "\\sin^{2}\\theta + \\cos^{2}\\theta = 1 \\\\\\\\[2pt] 2\\sin\\theta\\cos\\theta = \\sin 2\\theta", explanation: "The Pythagorean identity. Used to split \\(\\sin^3 = \\sin\\left(1-\\cos^2\\right)\\) or \\(\\cos^3 = \\cos\\left(1-\\sin^2\\right)\\) into pieces that admit a substitution.  Double-angle identity. Halves the work when integrating a \\(\\sin\\cos\\) product — converts to a single \\(\\sin\\) of doubled argument." }, { stepNumber: 2, description: "Expand the bracket.", workingLatex: "\\left(\\sin x - \\cos x\\right)^2 = \\sin^2 x - 2\\sin x\\cos x + \\cos^2 x", explanation: "Note the MINUS on the cross-term (because of the minus inside the bracket)." }, { stepNumber: 3, description: "Apply the identities.", workingLatex: "= 1 - \\sin 2x", explanation: "" }, { stepNumber: 4, description: "Integrate.", workingLatex: "\\displaystyle\\int \\left(1 - \\sin 2x\\right)\\,dx = x + \\frac{\\cos 2x}{2} + C", explanation: "\\(\\int \\sin 2x\\,dx = -\\cos 2x/2\\); the minus distributes through to give plus." } ], finalAnswer: "\\(x + \\frac{\\cos 2x}{2} + C\\)." } },
  { id: "y2in3-024", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 24", difficulty: "Foundation", questionText: "Find \\( \\displaystyle\\int \\left(\\cos^2 x - \\sin^2 x\\right) \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig", "double-angle"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identities used.", workingLatex: "\\cos^{2}\\theta = \\frac{1 + \\cos 2\\theta}{2} \\\\\\\\[2pt] \\sin^{2}\\theta = \\frac{1 - \\cos 2\\theta}{2}", explanation: "Half-angle identity for cosine. Rearranges \\(\\cos 2\\theta = 2\\cos^2\\theta - 1\\).  Half-angle (power-reduction) identity. Rearranges \\(\\cos 2\\theta = 1 - 2\\sin^2\\theta\\) — the form that lets us integrate \\(\\sin^2\\), which has no elementary antiderivative on its own." }, { stepNumber: 2, description: "Recognise the cosine double-angle identity.", workingLatex: "\\cos 2\\theta = \\cos^2\\theta - \\sin^2\\theta \\;\\Rightarrow\\; \\cos^2 x - \\sin^2 x = \\cos 2x", explanation: "This is the cleanest form of \\(\\cos 2\\theta\\)." }, { stepNumber: 3, description: "Integrate.", workingLatex: "\\displaystyle\\int \\cos 2x\\,dx = \\frac{\\sin 2x}{2} + C", explanation: "" } ], finalAnswer: "\\(\\frac{\\sin 2x}{2} + C\\)." } },
  { id: "y2in3-025", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 25", difficulty: "Foundation", questionText: "Find \\( \\displaystyle\\int \\frac{1 + \\cos 2x}{2} \\,dx \\) (same as \\(\\displaystyle\\int\\cos^2 x\\)).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig", "half-angle"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\cos^{2}\\theta = \\frac{1 + \\cos 2\\theta}{2}", explanation: "Half-angle identity for cosine. Rearranges \\(\\cos 2\\theta = 2\\cos^2\\theta - 1\\)." }, { stepNumber: 2, description: "Recognise the integrand as \\(\\cos^2 x\\).", workingLatex: "\\frac{1 + \\cos 2x}{2} = \\cos^2 x", explanation: "The integrand is already in the half-angle form." }, { stepNumber: 3, description: "Split the integral.", workingLatex: "\\displaystyle\\int \\frac{1 + \\cos 2x}{2}\\,dx = \\frac{1}{2}\\displaystyle\\int 1\\,dx + \\frac{1}{2}\\displaystyle\\int \\cos 2x\\,dx", explanation: "" }, { stepNumber: 4, description: "Integrate each piece.", workingLatex: "= \\frac{x}{2} + \\frac{\\sin 2x}{4} + C", explanation: "" } ], finalAnswer: "\\(\\frac{x}{2} + \\frac{\\sin 2x}{4} + C\\)." } },
  { id: "y2in3-026", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 26", difficulty: "Foundation", questionText: "Find \\( \\displaystyle\\int \\left(\\sec^2 x - 1\\right) \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\tan^{2}\\theta = \\sec^{2}\\theta - 1", explanation: "Pythagorean identity: divide \\(\\sin^2\\theta + \\cos^2\\theta = 1\\) through by \\(\\cos^2\\theta\\). Lets us turn \\(\\tan^2\\) into the standard \\(\\sec^2\\) antiderivative." }, { stepNumber: 2, description: "Identify each piece as a standard antiderivative.", workingLatex: "\\displaystyle\\int \\sec^2 x\\,dx = \\tan x; \\;\\; \\displaystyle\\int 1\\,dx = x", explanation: "No identity manipulation needed — both pieces integrate by inspection. (The integrand equals \\(\\tan^2 x\\) by Pythagoras, but it\\'s easier as written.)" }, { stepNumber: 3, description: "Split and combine.", workingLatex: "\\displaystyle\\int \\left(\\sec^2 x - 1\\right)\\,dx = \\tan x - x + C", explanation: "" } ], finalAnswer: "\\(\\tan x - x + C\\)." } },
  { id: "y2in3-027", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 27", difficulty: "Foundation", questionText: "Find \\( \\displaystyle\\int \\left(1 + \\tan^2 x\\right) \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig", "pythag"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\tan^{2}\\theta = \\sec^{2}\\theta - 1", explanation: "Pythagorean identity: divide \\(\\sin^2\\theta + \\cos^2\\theta = 1\\) through by \\(\\cos^2\\theta\\). Lets us turn \\(\\tan^2\\) into the standard \\(\\sec^2\\) antiderivative." }, { stepNumber: 2, description: "Use \\(1 + \\tan^2 x = \\sec^2 x\\).", workingLatex: "1 + \\tan^2 x = \\sec^2 x", explanation: "Direct rearrangement of the Pythagorean identity. The new form is a standard antiderivative." }, { stepNumber: 3, description: "Integrate.", workingLatex: "\\displaystyle\\int \\sec^2 x\\,dx = \\tan x + C", explanation: "" } ], finalAnswer: "\\(\\tan x + C\\)." } },
  { id: "y2in3-028", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 28", difficulty: "Standard", questionText: "Evaluate \\( \\displaystyle\\int_0^{\\pi/2} \\sin^2 x \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["definite", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\sin^{2}\\theta = \\frac{1 - \\cos 2\\theta}{2}", explanation: "Half-angle (power-reduction) identity. Rearranges \\(\\cos 2\\theta = 1 - 2\\sin^2\\theta\\) — the form that lets us integrate \\(\\sin^2\\), which has no elementary antiderivative on its own." }, { stepNumber: 2, description: "Find the antiderivative (see Q001).", workingLatex: "\\displaystyle\\int \\sin^2 x\\,dx = \\frac{x}{2} - \\frac{\\sin 2x}{4}", explanation: "" }, { stepNumber: 3, description: "Apply the Fundamental Theorem.", workingLatex: "\\displaystyle\\int_0^{\\pi/2} \\sin^2 x\\,dx = \\left[\\frac{x}{2} - \\frac{\\sin 2x}{4}\\right]_0^{\\pi/2}", explanation: "" }, { stepNumber: 4, description: "Evaluate at the upper limit.", workingLatex: "\\text{At } x = \\frac{\\pi}{2}: \\;\\; \\frac{\\pi}{4} - \\frac{\\sin \\pi}{4} = \\frac{\\pi}{4} - 0 = \\frac{\\pi}{4}", explanation: "\\(\\sin \\pi = 0\\)." }, { stepNumber: 5, description: "Evaluate at the lower limit and subtract.", workingLatex: "\\text{At } x = 0:\\; 0 - 0 = 0 \\;\\Rightarrow\\; \\text{answer} = \\frac{\\pi}{4}", explanation: "" } ], finalAnswer: "\\(\\frac{\\pi}{4}\\)." } },
  { id: "y2in3-029", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 29", difficulty: "Standard", questionText: "Evaluate \\( \\displaystyle\\int_0^{\\pi/2} \\cos^2 x \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["definite", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\cos^{2}\\theta = \\frac{1 + \\cos 2\\theta}{2}", explanation: "Half-angle identity for cosine. Rearranges \\(\\cos 2\\theta = 2\\cos^2\\theta - 1\\)." }, { stepNumber: 2, description: "Find the antiderivative (see Q002).", workingLatex: "\\displaystyle\\int \\cos^2 x\\,dx = \\frac{x}{2} + \\frac{\\sin 2x}{4}", explanation: "" }, { stepNumber: 3, description: "Apply the Fundamental Theorem and evaluate at both limits.", workingLatex: "\\left[\\frac{x}{2} + \\frac{\\sin 2x}{4}\\right]_0^{\\pi/2} = \\left(\\frac{\\pi}{4} + \\frac{\\sin \\pi}{4}\\right) - 0", explanation: "" }, { stepNumber: 4, description: "Simplify.", workingLatex: "= \\frac{\\pi}{4} + 0 = \\frac{\\pi}{4}", explanation: "Equal to \\(\\int_0^{\\pi/2} \\sin^2 x\\,dx\\) — by symmetry, \\(\\sin^2\\) and \\(\\cos^2\\) have equal average on any quarter-period." } ], finalAnswer: "\\(\\frac{\\pi}{4}\\)." } },
  { id: "y2in3-030", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 30", difficulty: "Standard", questionText: "Evaluate \\( \\displaystyle\\int_0^{\\pi} \\sin^2 x \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["definite", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\sin^{2}\\theta = \\frac{1 - \\cos 2\\theta}{2}", explanation: "Half-angle (power-reduction) identity. Rearranges \\(\\cos 2\\theta = 1 - 2\\sin^2\\theta\\) — the form that lets us integrate \\(\\sin^2\\), which has no elementary antiderivative on its own." }, { stepNumber: 2, description: "Find the antiderivative.", workingLatex: "\\displaystyle\\int \\sin^2 x\\,dx = \\frac{x}{2} - \\frac{\\sin 2x}{4}", explanation: "" }, { stepNumber: 3, description: "Apply the limits.", workingLatex: "\\left[\\frac{x}{2} - \\frac{\\sin 2x}{4}\\right]_0^{\\pi} = \\left(\\frac{\\pi}{2} - \\frac{\\sin 2\\pi}{4}\\right) - 0", explanation: "" }, { stepNumber: 4, description: "Evaluate.", workingLatex: "= \\frac{\\pi}{2} - 0 = \\frac{\\pi}{2}", explanation: "\\(\\sin 2\\pi = 0\\). Twice the \\(\\int_0^{\\pi/2}\\) result, as expected since the integral covers two half-periods." } ], finalAnswer: "\\(\\frac{\\pi}{2}\\)." } },
  { id: "y2in3-031", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 31", difficulty: "Standard", questionText: "Evaluate \\( \\displaystyle\\int_0^{\\pi/4} \\tan^2 x \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["definite", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\tan^{2}\\theta = \\sec^{2}\\theta - 1", explanation: "Pythagorean identity: divide \\(\\sin^2\\theta + \\cos^2\\theta = 1\\) through by \\(\\cos^2\\theta\\). Lets us turn \\(\\tan^2\\) into the standard \\(\\sec^2\\) antiderivative." }, { stepNumber: 2, description: "Convert using the Pythagorean identity.", workingLatex: "\\displaystyle\\int \\tan^2 x\\,dx = \\displaystyle\\int \\left(\\sec^2 x - 1\\right)\\,dx = \\tan x - x", explanation: "" }, { stepNumber: 3, description: "Apply the limits.", workingLatex: "\\left[\\tan x - x\\right]_0^{\\pi/4} = \\left(\\tan\\!\\frac{\\pi}{4} - \\frac{\\pi}{4}\\right) - 0", explanation: "" }, { stepNumber: 4, description: "Evaluate.", workingLatex: "= \\left(1 - \\frac{\\pi}{4}\\right) - 0 = 1 - \\frac{\\pi}{4}", explanation: "\\(\\tan\\left(\\pi/4\\right) = 1\\); answer is positive since \\(1 > \\pi/4 \\approx 0.79\\)." } ], finalAnswer: "\\(1 - \\frac{\\pi}{4}\\)." } },
  { id: "y2in3-032", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 32", difficulty: "Standard", questionText: "Evaluate \\( \\displaystyle\\int_0^{\\pi} \\sin^2\\left(2x\\right) \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["definite", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\sin^{2}\\theta = \\frac{1 - \\cos 2\\theta}{2}", explanation: "Half-angle (power-reduction) identity. Rearranges \\(\\cos 2\\theta = 1 - 2\\sin^2\\theta\\) — the form that lets us integrate \\(\\sin^2\\), which has no elementary antiderivative on its own." }, { stepNumber: 2, description: "Find the antiderivative (see Q003).", workingLatex: "\\displaystyle\\int \\sin^2\\left(2x\\right)\\,dx = \\frac{x}{2} - \\frac{\\sin 4x}{8}", explanation: "" }, { stepNumber: 3, description: "Apply the limits.", workingLatex: "\\left[\\frac{x}{2} - \\frac{\\sin 4x}{8}\\right]_0^{\\pi} = \\left(\\frac{\\pi}{2} - \\frac{\\sin 4\\pi}{8}\\right) - 0", explanation: "" }, { stepNumber: 4, description: "Evaluate.", workingLatex: "= \\frac{\\pi}{2} - 0 = \\frac{\\pi}{2}", explanation: "\\(\\sin 4\\pi = 0\\)." } ], finalAnswer: "\\(\\frac{\\pi}{2}\\)." } },
  { id: "y2in3-033", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 33", difficulty: "Standard", questionText: "Evaluate \\( \\displaystyle\\int_0^{\\pi/4} \\left(\\sin^2 x - \\cos^2 x\\right) \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["definite", "trig", "double-angle"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identities used.", workingLatex: "\\cos^{2}\\theta = \\frac{1 + \\cos 2\\theta}{2} \\\\\\\\[2pt] \\sin^{2}\\theta = \\frac{1 - \\cos 2\\theta}{2}", explanation: "Half-angle identity for cosine. Rearranges \\(\\cos 2\\theta = 2\\cos^2\\theta - 1\\).  Half-angle (power-reduction) identity. Rearranges \\(\\cos 2\\theta = 1 - 2\\sin^2\\theta\\) — the form that lets us integrate \\(\\sin^2\\), which has no elementary antiderivative on its own." }, { stepNumber: 2, description: "Use the double-angle identity in reverse.", workingLatex: "\\sin^2 x - \\cos^2 x = -\\left(\\cos^2 x - \\sin^2 x\\right) = -\\cos 2x", explanation: "Negative of Q024." }, { stepNumber: 3, description: "Find the antiderivative.", workingLatex: "\\displaystyle\\int -\\cos 2x\\,dx = -\\frac{\\sin 2x}{2}", explanation: "" }, { stepNumber: 4, description: "Apply the limits.", workingLatex: "\\left[-\\frac{\\sin 2x}{2}\\right]_0^{\\pi/4} = -\\frac{\\sin\\left(\\pi/2\\right)}{2} - 0", explanation: "" }, { stepNumber: 5, description: "Evaluate.", workingLatex: "= -\\frac{1}{2}", explanation: "\\(\\sin\\left(\\pi/2\\right) = 1\\); answer is negative because \\(\\sin^2 < \\cos^2\\) on \\([0, \\pi/4]\\)." } ], finalAnswer: "\\(-\\frac{1}{2}\\)." } },
  { id: "y2in3-034", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 34", difficulty: "Foundation", questionText: "Evaluate \\( \\displaystyle\\int_0^{\\pi/4} \\sin x\\cos x \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["definite", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "2\\sin\\theta\\cos\\theta = \\sin 2\\theta", explanation: "Double-angle identity. Halves the work when integrating a \\(\\sin\\cos\\) product — converts to a single \\(\\sin\\) of doubled argument." }, { stepNumber: 2, description: "Rewrite as half a sine using the double-angle identity.", workingLatex: "\\sin x\\cos x = \\frac{\\sin 2x}{2}", explanation: "" }, { stepNumber: 3, description: "Find the antiderivative.", workingLatex: "\\frac{1}{2}\\displaystyle\\int \\sin 2x\\,dx = -\\frac{\\cos 2x}{4}", explanation: "" }, { stepNumber: 4, description: "Apply the limits.", workingLatex: "\\left[-\\frac{\\cos 2x}{4}\\right]_0^{\\pi/4} = -\\frac{\\cos\\left(\\pi/2\\right)}{4} + \\frac{\\cos 0}{4} = 0 + \\frac{1}{4} = \\frac{1}{4}", explanation: "\\(\\cos\\left(\\pi/2\\right) = 0\\); \\(\\cos 0 = 1\\)." } ], finalAnswer: "\\(\\frac{1}{4}\\)." } },
  { id: "y2in3-035", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 35", difficulty: "Standard", questionText: "Find the area under \\(y = \\sin^2 x\\) from 0 to \\(\\pi\\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["definite", "trig", "area"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\sin^{2}\\theta = \\frac{1 - \\cos 2\\theta}{2}", explanation: "Half-angle (power-reduction) identity. Rearranges \\(\\cos 2\\theta = 1 - 2\\sin^2\\theta\\) — the form that lets us integrate \\(\\sin^2\\), which has no elementary antiderivative on its own." }, { stepNumber: 2, description: "Set up the area as a definite integral.", workingLatex: "\\text{Area} = \\displaystyle\\int_0^{\\pi} \\sin^2 x\\,dx", explanation: "\\(\\sin^2 x \\ge 0\\) on \\([0, \\pi]\\) (in fact everywhere), so the definite integral gives unsigned area directly." }, { stepNumber: 3, description: "Find the antiderivative (Q001) and apply the limits (Q030).", workingLatex: "\\left[\\frac{x}{2} - \\frac{\\sin 2x}{4}\\right]_0^{\\pi} = \\frac{\\pi}{2}", explanation: "" }, { stepNumber: 4, description: "Interpret.", workingLatex: "\\text{Area} = \\frac{\\pi}{2} \\approx 1.57", explanation: "Roughly half a rectangle of width \\(\\pi\\) and height \\(1\\) — since \\(\\sin^2 x\\) averages \\(1/2\\) over a half-period." } ], finalAnswer: "\\(\\frac{\\pi}{2}\\)." } },
  { id: "y2in3-036", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 36", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\sin x\\sin 3x \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["trig", "product-to-sum"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\sin A\\sin B = \\frac{1}{2}[\\cos\\left(A-B\\right) - \\cos\\left(A+B\\right)]", explanation: "Product-to-sum identity for two sines. Note the minus sign on the second term." }, { stepNumber: 2, description: "Apply product-to-sum with \\(A = x\\), \\(B = 3x\\).", workingLatex: "\\sin x\\sin 3x = \\frac{1}{2}\\!\\left[\\cos\\left(x - 3x\\right) - \\cos\\left(x + 3x\\right)\\right]", explanation: "" }, { stepNumber: 3, description: "Simplify the arguments.", workingLatex: "= \\frac{1}{2}\\!\\left[\\cos\\left(-2x\\right) - \\cos 4x\\right] = \\frac{1}{2}\\!\\left[\\cos 2x - \\cos 4x\\right]", explanation: "\\(\\cos\\) is even, so \\(\\cos\\left(-2x\\right) = \\cos 2x\\)." }, { stepNumber: 4, description: "Integrate each piece.", workingLatex: "\\displaystyle\\int \\sin x\\sin 3x\\,dx = \\frac{1}{2}\\displaystyle\\int \\cos 2x\\,dx - \\frac{1}{2}\\displaystyle\\int \\cos 4x\\,dx", explanation: "" }, { stepNumber: 5, description: "Apply the cosine rule and tidy.", workingLatex: "= \\frac{1}{2} \\cdot \\frac{\\sin 2x}{2} - \\frac{1}{2} \\cdot \\frac{\\sin 4x}{4} + C = \\frac{\\sin 2x}{4} - \\frac{\\sin 4x}{8} + C", explanation: "" } ], finalAnswer: "\\(\\frac{\\sin 2x}{4} - \\frac{\\sin 4x}{8} + C\\)." } },
  { id: "y2in3-037", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 37", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\cos 3x\\cos x \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["trig", "product-to-sum"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\cos A\\cos B = \\frac{1}{2}[\\cos\\left(A-B\\right) + \\cos\\left(A+B\\right)]", explanation: "Product-to-sum identity for two cosines." }, { stepNumber: 2, description: "Apply product-to-sum with \\(A = 3x\\), \\(B = x\\).", workingLatex: "\\cos 3x\\cos x = \\frac{1}{2}\\!\\left[\\cos\\left(3x - x\\right) + \\cos\\left(3x + x\\right)\\right] = \\frac{1}{2}\\!\\left[\\cos 2x + \\cos 4x\\right]", explanation: "" }, { stepNumber: 3, description: "Integrate each piece.", workingLatex: "\\displaystyle\\int \\cos 3x\\cos x\\,dx = \\frac{1}{2} \\cdot \\frac{\\sin 2x}{2} + \\frac{1}{2} \\cdot \\frac{\\sin 4x}{4} + C", explanation: "" }, { stepNumber: 4, description: "Tidy.", workingLatex: "= \\frac{\\sin 2x}{4} + \\frac{\\sin 4x}{8} + C", explanation: "" } ], finalAnswer: "\\(\\frac{\\sin 2x}{4} + \\frac{\\sin 4x}{8} + C\\)." } },
  { id: "y2in3-038", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 38", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\sin\\left(4x\\right)\\cos x \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["trig", "product-to-sum"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\sin A\\cos B = \\frac{1}{2}[\\sin\\left(A+B\\right) + \\sin\\left(A-B\\right)]", explanation: "Product-to-sum identity. Converts a product of \\(\\sin\\) and \\(\\cos\\) (at different multiples of \\(x\\)) into a sum of single sines, each of which integrates directly." }, { stepNumber: 2, description: "Apply product-to-sum with \\(A = 4x\\), \\(B = x\\).", workingLatex: "\\sin 4x\\cos x = \\frac{1}{2}\\!\\left[\\sin\\left(4x + x\\right) + \\sin\\left(4x - x\\right)\\right] = \\frac{1}{2}\\!\\left[\\sin 5x + \\sin 3x\\right]", explanation: "" }, { stepNumber: 3, description: "Integrate each piece using the sine rule.", workingLatex: "\\displaystyle\\int \\sin 4x\\cos x\\,dx = \\frac{1}{2}\\!\\left[-\\frac{\\cos 5x}{5} - \\frac{\\cos 3x}{3}\\right] + C", explanation: "" }, { stepNumber: 4, description: "Tidy.", workingLatex: "= -\\frac{\\cos 5x}{10} - \\frac{\\cos 3x}{6} + C", explanation: "" } ], finalAnswer: "\\(-\\frac{\\cos 5x}{10} - \\frac{\\cos 3x}{6} + C\\)." } },
  { id: "y2in3-039", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 39", difficulty: "Foundation", questionText: "Find \\( \\displaystyle\\int 2\\sin^2 x \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig", "half-angle"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\sin^{2}\\theta = \\frac{1 - \\cos 2\\theta}{2}", explanation: "Half-angle (power-reduction) identity. Rearranges \\(\\cos 2\\theta = 1 - 2\\sin^2\\theta\\) — the form that lets us integrate \\(\\sin^2\\), which has no elementary antiderivative on its own." }, { stepNumber: 2, description: "Apply the half-angle identity, multiplied by \\(2\\).", workingLatex: "2\\sin^2 x = 2 \\cdot \\frac{1 - \\cos 2x}{2} = 1 - \\cos 2x", explanation: "The factor of \\(2\\) cancels the denominator — no fractions to track." }, { stepNumber: 3, description: "Split and integrate.", workingLatex: "\\displaystyle\\int \\left(1 - \\cos 2x\\right)\\,dx = x - \\frac{\\sin 2x}{2} + C", explanation: "" } ], finalAnswer: "\\(x - \\frac{\\sin 2x}{2} + C\\)." } },
  { id: "y2in3-040", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 40", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\left(3\\cos^2 x - 1\\right) \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["trig", "half-angle"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\cos^{2}\\theta = \\frac{1 + \\cos 2\\theta}{2}", explanation: "Half-angle identity for cosine. Rearranges \\(\\cos 2\\theta = 2\\cos^2\\theta - 1\\)." }, { stepNumber: 2, description: "Apply the half-angle identity to \\(3\\cos^2 x\\).", workingLatex: "3\\cos^2 x = \\frac{3\\left(1 + \\cos 2x\\right)}{2} = \\frac{3}{2} + \\frac{3\\cos 2x}{2}", explanation: "" }, { stepNumber: 3, description: "Combine with the constant \\(-1\\).", workingLatex: "3\\cos^2 x - 1 = \\frac{3}{2} - 1 + \\frac{3\\cos 2x}{2} = \\frac{1}{2} + \\frac{3\\cos 2x}{2}", explanation: "\\(\\frac{3}{2} - 1 = \\frac{1}{2}\\)." }, { stepNumber: 4, description: "Split and integrate.", workingLatex: "\\displaystyle\\int \\left(\\frac{1}{2} + \\frac{3\\cos 2x}{2}\\right)\\,dx = \\frac{x}{2} + \\frac{3\\sin 2x}{4} + C", explanation: "" } ], finalAnswer: "\\(\\frac{x}{2} + \\frac{3\\sin 2x}{4} + C\\)." } },
  { id: "y2in3-041", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 41", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\sin 2x\\cos 2x \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig", "double-angle"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "2\\sin\\theta\\cos\\theta = \\sin 2\\theta", explanation: "Double-angle identity. Halves the work when integrating a \\(\\sin\\cos\\) product — converts to a single \\(\\sin\\) of doubled argument." }, { stepNumber: 2, description: "Apply the double-angle identity with \\(\\theta = 2x\\).", workingLatex: "\\sin 2x\\cos 2x = \\frac{\\sin 4x}{2}", explanation: "" }, { stepNumber: 3, description: "Set up and integrate.", workingLatex: "\\displaystyle\\int \\frac{\\sin 4x}{2}\\,dx = -\\frac{\\cos 4x}{8} + C", explanation: "\\(\\int \\sin 4x\\,dx = -\\cos 4x/4\\); halve to get \\(/8\\)." } ], finalAnswer: "\\(-\\frac{\\cos 4x}{8} + C\\)." } },
  { id: "y2in3-042", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 42", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\sin^2 x\\cos^2 x \\,dx \\).", marks: 4, examStyle: false, yearCreated: 2026, tags: ["trig", "double-angle", "half-angle"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identities used.", workingLatex: "2\\sin\\theta\\cos\\theta = \\sin 2\\theta \\\\\\\\[2pt] \\sin^{2}\\theta = \\frac{1 - \\cos 2\\theta}{2}", explanation: "Double-angle identity. Halves the work when integrating a \\(\\sin\\cos\\) product — converts to a single \\(\\sin\\) of doubled argument.  Half-angle (power-reduction) identity. Rearranges \\(\\cos 2\\theta = 1 - 2\\sin^2\\theta\\) — the form that lets us integrate \\(\\sin^2\\), which has no elementary antiderivative on its own." }, { stepNumber: 2, description: "Combine \\(\\sin x\\cos x\\) into a single \\(\\sin 2x\\).", workingLatex: "\\sin^2 x\\cos^2 x = \\left(\\sin x\\cos x\\right)^2 = \\left(\\frac{\\sin 2x}{2}\\right)^2 = \\frac{\\sin^2 2x}{4}", explanation: "Squaring the double-angle form reduces a four-factor integral to a single \\(\\sin^2\\) integral — the standard trick." }, { stepNumber: 3, description: "Apply the half-angle identity to \\(\\sin^2 2x\\).", workingLatex: "\\sin^2 2x = \\frac{1 - \\cos 4x}{2}", explanation: "" }, { stepNumber: 4, description: "Combine.", workingLatex: "\\sin^2 x\\cos^2 x = \\frac{1}{4} \\cdot \\frac{1 - \\cos 4x}{2} = \\frac{1 - \\cos 4x}{8}", explanation: "" }, { stepNumber: 5, description: "Split and integrate.", workingLatex: "\\displaystyle\\int \\frac{1 - \\cos 4x}{8}\\,dx = \\frac{x}{8} - \\frac{1}{8} \\cdot \\frac{\\sin 4x}{4} + C = \\frac{x}{8} - \\frac{\\sin 4x}{32} + C", explanation: "" } ], finalAnswer: "\\(\\frac{x}{8} - \\frac{\\sin 4x}{32} + C\\)." } },
  { id: "y2in3-043", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 43", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\tan x \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["trig", "u-substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\text{If } u = g(x),\\;\\; du = g\\'(x)\\,dx \\;\\Rightarrow\\; \\displaystyle\\int f(g(x))\\,g\\'(x)\\,dx = \\displaystyle\\int f(u)\\,du", explanation: "Reverse-chain-rule (substitution). Used here whenever the integrand contains a function and its derivative as a factor — pick the inner part as \\(u\\)." }, { stepNumber: 2, description: "Rewrite \\(\\tan x\\) as a quotient.", workingLatex: "\\tan x = \\frac{\\sin x}{\\cos x}", explanation: "" }, { stepNumber: 3, description: "Spot the function-and-its-derivative pattern.", workingLatex: "\\frac{d}{dx}\\cos x = -\\sin x \\;\\Rightarrow\\; \\text{numerator } \\sin x\\,dx = -d\\left(\\cos x\\right)", explanation: "The numerator is the negative derivative of the denominator — classic u-sub setup." }, { stepNumber: 4, description: "Substitute \\(u = \\cos x\\).", workingLatex: "u = \\cos x, \\;\\; du = -\\sin x\\,dx \\;\\Rightarrow\\; \\sin x\\,dx = -du", explanation: "" }, { stepNumber: 5, description: "Convert the integral.", workingLatex: "\\displaystyle\\int \\tan x\\,dx = \\displaystyle\\int \\frac{-du}{u} = -\\displaystyle\\int \\frac{du}{u}", explanation: "" }, { stepNumber: 6, description: "Integrate and back-substitute.", workingLatex: "= -\\ln|u| + C = -\\ln|\\cos x| + C", explanation: "" }, { stepNumber: 7, description: "Equivalent form.", workingLatex: "-\\ln|\\cos x| = \\ln\\!\\left|\\frac{1}{\\cos x}\\right| = \\ln|\\sec x|", explanation: "\\(-\\ln a = \\ln\\left(1/a\\right)\\); both forms appear in mark schemes." } ], finalAnswer: "\\(-\\ln|\\cos x| + C = \\ln|\\sec x| + C\\)." } },
  { id: "y2in3-044", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 44", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\cot x \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["trig", "u-substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\text{If } u = g(x),\\;\\; du = g\\'(x)\\,dx \\;\\Rightarrow\\; \\displaystyle\\int f(g(x))\\,g\\'(x)\\,dx = \\displaystyle\\int f(u)\\,du", explanation: "Reverse-chain-rule (substitution). Used here whenever the integrand contains a function and its derivative as a factor — pick the inner part as \\(u\\)." }, { stepNumber: 2, description: "Rewrite \\(\\cot x\\) as a quotient.", workingLatex: "\\cot x = \\frac{\\cos x}{\\sin x}", explanation: "" }, { stepNumber: 3, description: "Substitute \\(u = \\sin x\\).", workingLatex: "u = \\sin x,\\;\\; du = \\cos x\\,dx", explanation: "Numerator is exactly the derivative of the denominator — no minus this time." }, { stepNumber: 4, description: "Convert the integral.", workingLatex: "\\displaystyle\\int \\cot x\\,dx = \\displaystyle\\int \\frac{du}{u}", explanation: "" }, { stepNumber: 5, description: "Integrate and back-substitute.", workingLatex: "= \\ln|u| + C = \\ln|\\sin x| + C", explanation: "" } ], finalAnswer: "\\(\\ln|\\sin x| + C\\)." } },
  { id: "y2in3-045", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 45", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\sec x \\,dx \\).", marks: 4, examStyle: false, yearCreated: 2026, tags: ["trig", "trick"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\displaystyle\\int \\sec x\\,dx = \\ln|\\sec x + \\tan x| + C", explanation: "Derived by multiplying top and bottom by \\(\\sec x + \\tan x\\) — a classic textbook trick — to make the numerator the derivative of the denominator." }, { stepNumber: 2, description: "Multiply top and bottom by \\(\\sec x + \\tan x\\).", workingLatex: "\\sec x = \\frac{\\sec x\\,\\left(\\sec x + \\tan x\\right)}{\\sec x + \\tan x}", explanation: "The classic textbook trick. Goal: make the numerator the derivative of the denominator so a substitution works." }, { stepNumber: 3, description: "Expand the numerator.", workingLatex: "= \\frac{\\sec^2 x + \\sec x\\tan x}{\\sec x + \\tan x}", explanation: "" }, { stepNumber: 4, description: "Recognise that the numerator is the derivative of the denominator.", workingLatex: "\\frac{d}{dx}\\left(\\sec x + \\tan x\\right) = \\sec x\\tan x + \\sec^2 x", explanation: "Matches the numerator exactly." }, { stepNumber: 5, description: "Substitute \\(u = \\sec x + \\tan x\\).", workingLatex: "du = \\left(\\sec^2 x + \\sec x\\tan x\\right)\\,dx \\;\\Rightarrow\\; \\displaystyle\\int \\sec x\\,dx = \\displaystyle\\int \\frac{du}{u}", explanation: "" }, { stepNumber: 6, description: "Integrate and back-substitute.", workingLatex: "= \\ln|u| + C = \\ln|\\sec x + \\tan x| + C", explanation: "" } ], finalAnswer: "\\(\\ln|\\sec x + \\tan x| + C\\)." } },
  { id: "y2in3-046", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 46", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\csc x \\,dx \\).", marks: 4, examStyle: false, yearCreated: 2026, tags: ["trig", "trick"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\displaystyle\\int \\csc x\\,dx = -\\ln|\\csc x + \\cot x| + C", explanation: "Mirror of the \\(\\sec\\) trick: multiply top and bottom by \\(\\csc x + \\cot x\\) and use that the numerator is the negative derivative of the denominator." }, { stepNumber: 2, description: "Multiply top and bottom by \\(\\csc x + \\cot x\\).", workingLatex: "\\csc x = \\frac{\\csc x\\,\\left(\\csc x + \\cot x\\right)}{\\csc x + \\cot x} = \\frac{\\csc^2 x + \\csc x\\cot x}{\\csc x + \\cot x}", explanation: "Mirror of the \\(\\sec x\\) trick." }, { stepNumber: 3, description: "Differentiate the denominator.", workingLatex: "\\frac{d}{dx}\\left(\\csc x + \\cot x\\right) = -\\csc x\\cot x - \\csc^2 x = -\\left(\\csc^2 x + \\csc x\\cot x\\right)", explanation: "Negative of the numerator — so we pick up an overall minus." }, { stepNumber: 4, description: "Substitute \\(u = \\csc x + \\cot x\\).", workingLatex: "du = -\\left(\\csc^2 x + \\csc x\\cot x\\right)\\,dx \\;\\Rightarrow\\; \\displaystyle\\int \\csc x\\,dx = -\\displaystyle\\int \\frac{du}{u}", explanation: "" }, { stepNumber: 5, description: "Integrate and back-substitute.", workingLatex: "= -\\ln|u| + C = -\\ln|\\csc x + \\cot x| + C", explanation: "" } ], finalAnswer: "\\(-\\ln|\\csc x + \\cot x| + C\\)." } },
  { id: "y2in3-047", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 47", difficulty: "Standard", questionText: "Evaluate \\( \\displaystyle\\int_0^{\\pi/2} \\sin^2\\left(2x\\right) \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["definite", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\sin^{2}\\theta = \\frac{1 - \\cos 2\\theta}{2}", explanation: "Half-angle (power-reduction) identity. Rearranges \\(\\cos 2\\theta = 1 - 2\\sin^2\\theta\\) — the form that lets us integrate \\(\\sin^2\\), which has no elementary antiderivative on its own." }, { stepNumber: 2, description: "Find the antiderivative (see Q003).", workingLatex: "\\displaystyle\\int \\sin^2\\left(2x\\right)\\,dx = \\frac{x}{2} - \\frac{\\sin 4x}{8}", explanation: "" }, { stepNumber: 3, description: "Apply the limits.", workingLatex: "\\left[\\frac{x}{2} - \\frac{\\sin 4x}{8}\\right]_0^{\\pi/2} = \\left(\\frac{\\pi}{4} - \\frac{\\sin 2\\pi}{8}\\right) - 0", explanation: "" }, { stepNumber: 4, description: "Evaluate.", workingLatex: "= \\frac{\\pi}{4} - 0 = \\frac{\\pi}{4}", explanation: "\\(\\sin 2\\pi = 0\\)." } ], finalAnswer: "\\(\\frac{\\pi}{4}\\)." } },
  { id: "y2in3-048", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 48", difficulty: "Standard", questionText: "Evaluate \\( \\displaystyle\\int_0^{\\pi/3} \\tan^2 x \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["definite", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\tan^{2}\\theta = \\sec^{2}\\theta - 1", explanation: "Pythagorean identity: divide \\(\\sin^2\\theta + \\cos^2\\theta = 1\\) through by \\(\\cos^2\\theta\\). Lets us turn \\(\\tan^2\\) into the standard \\(\\sec^2\\) antiderivative." }, { stepNumber: 2, description: "Find the antiderivative.", workingLatex: "\\displaystyle\\int \\tan^2 x\\,dx = \\tan x - x", explanation: "" }, { stepNumber: 3, description: "Apply the limits.", workingLatex: "\\left[\\tan x - x\\right]_0^{\\pi/3} = \\left(\\tan\\!\\frac{\\pi}{3} - \\frac{\\pi}{3}\\right) - 0", explanation: "" }, { stepNumber: 4, description: "Evaluate.", workingLatex: "= \\sqrt 3 - \\frac{\\pi}{3}", explanation: "\\(\\tan\\left(\\pi/3\\right) = \\sqrt 3\\)." } ], finalAnswer: "\\(\\sqrt 3 - \\frac{\\pi}{3}\\)." } },
  { id: "y2in3-049", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 49", difficulty: "Standard", questionText: "Evaluate \\( \\displaystyle\\int_0^{\\pi/2} \\left(\\sin x + \\cos x\\right)^2 \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["definite", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identities used.", workingLatex: "\\sin^{2}\\theta + \\cos^{2}\\theta = 1 \\\\\\\\[2pt] 2\\sin\\theta\\cos\\theta = \\sin 2\\theta", explanation: "The Pythagorean identity. Used to split \\(\\sin^3 = \\sin\\left(1-\\cos^2\\right)\\) or \\(\\cos^3 = \\cos\\left(1-\\sin^2\\right)\\) into pieces that admit a substitution.  Double-angle identity. Halves the work when integrating a \\(\\sin\\cos\\) product — converts to a single \\(\\sin\\) of doubled argument." }, { stepNumber: 2, description: "Expand and simplify (see Q022).", workingLatex: "\\left(\\sin x + \\cos x\\right)^2 = 1 + \\sin 2x", explanation: "Pythagoras + double-angle." }, { stepNumber: 3, description: "Find the antiderivative.", workingLatex: "\\displaystyle\\int \\left(1 + \\sin 2x\\right)\\,dx = x - \\frac{\\cos 2x}{2}", explanation: "" }, { stepNumber: 4, description: "Apply the limits.", workingLatex: "\\left[x - \\frac{\\cos 2x}{2}\\right]_0^{\\pi/2} = \\left(\\frac{\\pi}{2} - \\frac{\\cos \\pi}{2}\\right) - \\left(0 - \\frac{\\cos 0}{2}\\right)", explanation: "" }, { stepNumber: 5, description: "Evaluate.", workingLatex: "= \\left(\\frac{\\pi}{2} - \\frac{-1}{2}\\right) - \\left(-\\frac{1}{2}\\right) = \\frac{\\pi}{2} + \\frac{1}{2} + \\frac{1}{2} = \\frac{\\pi}{2} + 1", explanation: "\\(\\cos \\pi = -1\\); \\(\\cos 0 = 1\\). Mind the cascade of minus signs." } ], finalAnswer: "\\(\\frac{\\pi}{2} + 1\\)." } },
  { id: "y2in3-050", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 50", difficulty: "Standard", questionText: "Evaluate \\( \\displaystyle\\int_0^{\\pi/6} \\cos^2\\left(3x\\right) \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["definite", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\cos^{2}\\theta = \\frac{1 + \\cos 2\\theta}{2}", explanation: "Half-angle identity for cosine. Rearranges \\(\\cos 2\\theta = 2\\cos^2\\theta - 1\\)." }, { stepNumber: 2, description: "Find the antiderivative (see Q004).", workingLatex: "\\displaystyle\\int \\cos^2\\left(3x\\right)\\,dx = \\frac{x}{2} + \\frac{\\sin 6x}{12}", explanation: "" }, { stepNumber: 3, description: "Apply the limits.", workingLatex: "\\left[\\frac{x}{2} + \\frac{\\sin 6x}{12}\\right]_0^{\\pi/6} = \\left(\\frac{\\pi}{12} + \\frac{\\sin \\pi}{12}\\right) - 0", explanation: "" }, { stepNumber: 4, description: "Evaluate.", workingLatex: "= \\frac{\\pi}{12} + 0 = \\frac{\\pi}{12}", explanation: "\\(\\sin \\pi = 0\\)." } ], finalAnswer: "\\(\\frac{\\pi}{12}\\)." } },
  { id: "y2in3-051", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 51", difficulty: "Foundation", questionText: "Find \\( \\displaystyle\\int \\left(1 - 2\\cos^2 x\\right) \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig", "double-angle"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\cos^{2}\\theta = \\frac{1 + \\cos 2\\theta}{2}", explanation: "Half-angle identity for cosine. Rearranges \\(\\cos 2\\theta = 2\\cos^2\\theta - 1\\)." }, { stepNumber: 2, description: "Use the half-angle identity multiplied by \\(2\\).", workingLatex: "2\\cos^2 x = 1 + \\cos 2x \\;\\Rightarrow\\; 1 - 2\\cos^2 x = -\\cos 2x", explanation: "The two constant terms cancel; left with \\(-\\cos 2x\\)." }, { stepNumber: 3, description: "Integrate.", workingLatex: "\\displaystyle\\int -\\cos 2x\\,dx = -\\frac{\\sin 2x}{2} + C", explanation: "" } ], finalAnswer: "\\(-\\frac{\\sin 2x}{2} + C\\)." } },
  { id: "y2in3-052", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 52", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\frac{1}{1 + \\cos 2x} \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["trig", "half-angle"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\cos^{2}\\theta = \\frac{1 + \\cos 2\\theta}{2}", explanation: "Half-angle identity for cosine. Rearranges \\(\\cos 2\\theta = 2\\cos^2\\theta - 1\\)." }, { stepNumber: 2, description: "Rewrite the denominator using the half-angle identity.", workingLatex: "1 + \\cos 2x = 2\\cos^2 x", explanation: "Rearrangement of \\(\\cos^2 x = \\left(1+\\cos 2x\\right)/2\\)." }, { stepNumber: 3, description: "Simplify the integrand.", workingLatex: "\\frac{1}{1 + \\cos 2x} = \\frac{1}{2\\cos^2 x} = \\frac{1}{2}\\sec^2 x", explanation: "\\(1/\\cos^2 = \\sec^2\\)." }, { stepNumber: 4, description: "Integrate.", workingLatex: "\\displaystyle\\int \\frac{1}{2}\\sec^2 x\\,dx = \\frac{\\tan x}{2} + C", explanation: "" } ], finalAnswer: "\\(\\frac{\\tan x}{2} + C\\)." } },
  { id: "y2in3-053", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 53", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\frac{1}{1 - \\cos 2x} \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["trig", "half-angle"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\sin^{2}\\theta = \\frac{1 - \\cos 2\\theta}{2}", explanation: "Half-angle (power-reduction) identity. Rearranges \\(\\cos 2\\theta = 1 - 2\\sin^2\\theta\\) — the form that lets us integrate \\(\\sin^2\\), which has no elementary antiderivative on its own." }, { stepNumber: 2, description: "Rewrite the denominator using the half-angle identity.", workingLatex: "1 - \\cos 2x = 2\\sin^2 x", explanation: "" }, { stepNumber: 3, description: "Simplify the integrand.", workingLatex: "\\frac{1}{1 - \\cos 2x} = \\frac{1}{2\\sin^2 x} = \\frac{1}{2}\\csc^2 x", explanation: "" }, { stepNumber: 4, description: "Integrate.", workingLatex: "\\displaystyle\\int \\frac{1}{2}\\csc^2 x\\,dx = -\\frac{\\cot x}{2} + C", explanation: "\\(\\int \\csc^2 x\\,dx = -\\cot x\\)." } ], finalAnswer: "\\(-\\frac{\\cot x}{2} + C\\)." } },
  { id: "y2in3-054", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 54", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\frac{\\sin x + \\cos x}{\\cos x} \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\displaystyle\\int \\tan x\\,dx = -\\ln|\\cos x| + C", explanation: "Derived by the substitution \\(u = \\cos x\\): \\(\\tan x\\,dx = -du/u\\)." }, { stepNumber: 2, description: "Split the fraction term-by-term.", workingLatex: "\\frac{\\sin x + \\cos x}{\\cos x} = \\frac{\\sin x}{\\cos x} + \\frac{\\cos x}{\\cos x} = \\tan x + 1", explanation: "" }, { stepNumber: 3, description: "Split the integral.", workingLatex: "\\displaystyle\\int \\left(\\tan x + 1\\right)\\,dx = \\displaystyle\\int \\tan x\\,dx + \\displaystyle\\int 1\\,dx", explanation: "" }, { stepNumber: 4, description: "Apply the antiderivatives.", workingLatex: "= -\\ln|\\cos x| + x + C", explanation: "See Q043 for \\(\\int \\tan x\\,dx\\)." } ], finalAnswer: "\\(-\\ln|\\cos x| + x + C\\)." } },
  { id: "y2in3-055", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 55", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\left(\\sin x + \\cos x\\right)\\left(\\sin x - \\cos x\\right) \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig", "double-angle"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identities used.", workingLatex: "\\cos^{2}\\theta = \\frac{1 + \\cos 2\\theta}{2} \\\\\\\\[2pt] \\sin^{2}\\theta = \\frac{1 - \\cos 2\\theta}{2}", explanation: "Half-angle identity for cosine. Rearranges \\(\\cos 2\\theta = 2\\cos^2\\theta - 1\\).  Half-angle (power-reduction) identity. Rearranges \\(\\cos 2\\theta = 1 - 2\\sin^2\\theta\\) — the form that lets us integrate \\(\\sin^2\\), which has no elementary antiderivative on its own." }, { stepNumber: 2, description: "Recognise the difference-of-squares.", workingLatex: "\\left(\\sin x + \\cos x\\right)\\left(\\sin x - \\cos x\\right) = \\sin^2 x - \\cos^2 x", explanation: "\\(\\left(a + b\\right)\\left(a - b\\right) = a^2 - b^2\\)." }, { stepNumber: 3, description: "Simplify using the cosine double-angle identity.", workingLatex: "\\sin^2 x - \\cos^2 x = -\\left(\\cos^2 x - \\sin^2 x\\right) = -\\cos 2x", explanation: "" }, { stepNumber: 4, description: "Integrate.", workingLatex: "\\displaystyle\\int -\\cos 2x\\,dx = -\\frac{\\sin 2x}{2} + C", explanation: "" } ], finalAnswer: "\\(-\\frac{\\sin 2x}{2} + C\\)." } },
  { id: "y2in3-056", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 56", difficulty: "Foundation", questionText: "Find \\( \\displaystyle\\int \\left(\\sin^2 x - \\cos^2 x\\right) \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig", "double-angle"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identities used.", workingLatex: "\\cos^{2}\\theta = \\frac{1 + \\cos 2\\theta}{2} \\\\\\\\[2pt] \\sin^{2}\\theta = \\frac{1 - \\cos 2\\theta}{2}", explanation: "Half-angle identity for cosine. Rearranges \\(\\cos 2\\theta = 2\\cos^2\\theta - 1\\).  Half-angle (power-reduction) identity. Rearranges \\(\\cos 2\\theta = 1 - 2\\sin^2\\theta\\) — the form that lets us integrate \\(\\sin^2\\), which has no elementary antiderivative on its own." }, { stepNumber: 2, description: "Recognise as negative of the cosine double-angle identity.", workingLatex: "\\sin^2 x - \\cos^2 x = -\\cos 2x", explanation: "" }, { stepNumber: 3, description: "Integrate.", workingLatex: "\\displaystyle\\int -\\cos 2x\\,dx = -\\frac{\\sin 2x}{2} + C", explanation: "" } ], finalAnswer: "\\(-\\frac{\\sin 2x}{2} + C\\)." } },
  { id: "y2in3-057", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 57", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\left(2\\cos x - \\sin x\\right)^2 \\,dx \\).", marks: 4, examStyle: false, yearCreated: 2026, tags: ["trig", "expand"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identities used.", workingLatex: "\\sin^{2}\\theta = \\frac{1 - \\cos 2\\theta}{2} \\\\\\\\[2pt] \\cos^{2}\\theta = \\frac{1 + \\cos 2\\theta}{2} \\\\\\\\[2pt] 2\\sin\\theta\\cos\\theta = \\sin 2\\theta", explanation: "Half-angle (power-reduction) identity. Rearranges \\(\\cos 2\\theta = 1 - 2\\sin^2\\theta\\) — the form that lets us integrate \\(\\sin^2\\), which has no elementary antiderivative on its own.  Half-angle identity for cosine. Rearranges \\(\\cos 2\\theta = 2\\cos^2\\theta - 1\\).  Double-angle identity. Halves the work when integrating a \\(\\sin\\cos\\) product — converts to a single \\(\\sin\\) of doubled argument." }, { stepNumber: 2, description: "Expand the bracket.", workingLatex: "\\left(2\\cos x - \\sin x\\right)^2 = 4\\cos^2 x - 4\\sin x\\cos x + \\sin^2 x", explanation: "\\(\\left(a - b\\right)^2 = a^2 - 2ab + b^2\\) with \\(a = 2\\cos x\\), \\(b = \\sin x\\)." }, { stepNumber: 3, description: "Apply the half-angle identities.", workingLatex: "4\\cos^2 x = 2\\left(1 + \\cos 2x\\right), \\;\\; \\sin^2 x = \\frac{1 - \\cos 2x}{2}", explanation: "" }, { stepNumber: 4, description: "Apply the double-angle identity to the cross-term.", workingLatex: "4\\sin x\\cos x = 2 \\cdot 2\\sin x\\cos x = 2\\sin 2x", explanation: "" }, { stepNumber: 5, description: "Combine all three pieces.", workingLatex: "\\left(2\\cos x - \\sin x\\right)^2 = 2\\left(1 + \\cos 2x\\right) - 2\\sin 2x + \\frac{1 - \\cos 2x}{2}", explanation: "" }, { stepNumber: 6, description: "Simplify constants and \\(\\cos 2x\\) coefficients.", workingLatex: "= 2 + 2\\cos 2x - 2\\sin 2x + \\frac{1}{2} - \\frac{\\cos 2x}{2} = \\frac{5}{2} + \\frac{3\\cos 2x}{2} - 2\\sin 2x", explanation: "Constants: \\(2 + \\frac{1}{2} = \\frac{5}{2}\\). Cosine terms: \\(2 - \\frac{1}{2} = \\frac{3}{2}\\)." }, { stepNumber: 7, description: "Integrate term-by-term.", workingLatex: "\\displaystyle\\int \\left(\\frac{5}{2} + \\frac{3\\cos 2x}{2} - 2\\sin 2x\\right)\\,dx = \\frac{5x}{2} + \\frac{3\\sin 2x}{4} + \\cos 2x + C", explanation: "\\(\\int 2\\sin 2x\\,dx = -\\cos 2x\\); the leading minus combines with the term\\'s minus to give +." } ], finalAnswer: "\\(\\frac{5x}{2} + \\frac{3\\sin 2x}{4} + \\cos 2x + C\\)." } },
  { id: "y2in3-058", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 58", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\frac{\\sin x}{\\cos^2 x} \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["trig", "u-substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\text{If } u = g(x),\\;\\; du = g\\'(x)\\,dx \\;\\Rightarrow\\; \\displaystyle\\int f(g(x))\\,g\\'(x)\\,dx = \\displaystyle\\int f(u)\\,du", explanation: "Reverse-chain-rule (substitution). Used here whenever the integrand contains a function and its derivative as a factor — pick the inner part as \\(u\\)." }, { stepNumber: 2, description: "Identify the function-and-its-derivative pattern.", workingLatex: "\\frac{d}{dx}\\cos x = -\\sin x", explanation: "\\(\\cos^2 x\\) is a function of \\(\\cos x\\); the numerator \\(\\sin x\\) is its negative derivative." }, { stepNumber: 3, description: "Substitute \\(u = \\cos x\\).", workingLatex: "u = \\cos x,\\;\\; du = -\\sin x\\,dx \\;\\Rightarrow\\; \\sin x\\,dx = -du", explanation: "" }, { stepNumber: 4, description: "Convert the integral.", workingLatex: "\\displaystyle\\int \\frac{\\sin x}{\\cos^2 x}\\,dx = \\displaystyle\\int \\frac{-du}{u^2} = -\\displaystyle\\int u^{-2}\\,du", explanation: "" }, { stepNumber: 5, description: "Integrate.", workingLatex: "-\\displaystyle\\int u^{-2}\\,du = -\\left(\\frac{u^{-1}}{-1}\\right) + C = u^{-1} + C = \\frac{1}{u} + C", explanation: "" }, { stepNumber: 6, description: "Back-substitute.", workingLatex: "= \\frac{1}{\\cos x} + C = \\sec x + C", explanation: "" } ], finalAnswer: "\\(\\sec x + C\\)." } },
  { id: "y2in3-059", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 59", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\frac{\\cos x}{\\sin^2 x} \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["trig", "u-substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\text{If } u = g(x),\\;\\; du = g\\'(x)\\,dx \\;\\Rightarrow\\; \\displaystyle\\int f(g(x))\\,g\\'(x)\\,dx = \\displaystyle\\int f(u)\\,du", explanation: "Reverse-chain-rule (substitution). Used here whenever the integrand contains a function and its derivative as a factor — pick the inner part as \\(u\\)." }, { stepNumber: 2, description: "Substitute \\(u = \\sin x\\).", workingLatex: "u = \\sin x,\\;\\; du = \\cos x\\,dx", explanation: "" }, { stepNumber: 3, description: "Convert the integral.", workingLatex: "\\displaystyle\\int \\frac{\\cos x}{\\sin^2 x}\\,dx = \\displaystyle\\int \\frac{du}{u^2}", explanation: "" }, { stepNumber: 4, description: "Integrate.", workingLatex: "\\displaystyle\\int u^{-2}\\,du = -u^{-1} + C", explanation: "" }, { stepNumber: 5, description: "Back-substitute.", workingLatex: "= -\\frac{1}{\\sin x} + C = -\\csc x + C", explanation: "" } ], finalAnswer: "\\(-\\csc x + C\\)." } },
  { id: "y2in3-060", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 60", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\frac{1}{\\sin^2 x\\cos^2 x} \\,dx \\).", marks: 4, examStyle: false, yearCreated: 2026, tags: ["trig", "double-angle"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "2\\sin\\theta\\cos\\theta = \\sin 2\\theta", explanation: "Double-angle identity. Halves the work when integrating a \\(\\sin\\cos\\) product — converts to a single \\(\\sin\\) of doubled argument." }, { stepNumber: 2, description: "Combine the denominator using the double-angle identity.", workingLatex: "\\sin x\\cos x = \\frac{\\sin 2x}{2} \\;\\Rightarrow\\; \\sin^2 x\\cos^2 x = \\frac{\\sin^2 2x}{4}", explanation: "Squaring the double-angle form reduces the four-factor denominator to a single \\(\\sin^2 2x\\)." }, { stepNumber: 3, description: "Reciprocate.", workingLatex: "\\frac{1}{\\sin^2 x\\cos^2 x} = \\frac{4}{\\sin^2 2x} = 4\\csc^2 2x", explanation: "" }, { stepNumber: 4, description: "Apply the \\(\\csc^2\\) rule with \\(a = 2\\).", workingLatex: "\\displaystyle\\int 4\\csc^2 2x\\,dx = 4 \\cdot \\left(-\\frac{\\cot 2x}{2}\\right) + C", explanation: "" }, { stepNumber: 5, description: "Tidy.", workingLatex: "= -2\\cot 2x + C", explanation: "" } ], finalAnswer: "\\(-2\\cot 2x + C\\)." } },
  { id: "y2in3-061", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 61", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\frac{\\cos 2x}{\\cos x - \\sin x} \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["trig", "double-angle"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identities used.", workingLatex: "\\cos^{2}\\theta = \\frac{1 + \\cos 2\\theta}{2} \\\\\\\\[2pt] \\sin^{2}\\theta = \\frac{1 - \\cos 2\\theta}{2}", explanation: "Half-angle identity for cosine. Rearranges \\(\\cos 2\\theta = 2\\cos^2\\theta - 1\\).  Half-angle (power-reduction) identity. Rearranges \\(\\cos 2\\theta = 1 - 2\\sin^2\\theta\\) — the form that lets us integrate \\(\\sin^2\\), which has no elementary antiderivative on its own." }, { stepNumber: 2, description: "Use the double-angle identity for \\(\\cos 2x\\) and factor as difference of squares.", workingLatex: "\\cos 2x = \\cos^2 x - \\sin^2 x = \\left(\\cos x - \\sin x\\right)\\left(\\cos x + \\sin x\\right)", explanation: "Always try this when you see \\(\\cos 2x\\) with a \\(\\cos x \\pm \\sin x\\) in the denominator." }, { stepNumber: 3, description: "Cancel the common factor in the integrand.", workingLatex: "\\frac{\\cos 2x}{\\cos x - \\sin x} = \\frac{\\left(\\cos x - \\sin x\\right)\\left(\\cos x + \\sin x\\right)}{\\cos x - \\sin x} = \\cos x + \\sin x", explanation: "" }, { stepNumber: 4, description: "Integrate term-by-term.", workingLatex: "\\displaystyle\\int \\left(\\cos x + \\sin x\\right)\\,dx = \\sin x - \\cos x + C", explanation: "\\(\\int \\cos x = \\sin x\\); \\(\\int \\sin x = -\\cos x\\)." } ], finalAnswer: "\\(\\sin x - \\cos x + C\\)." } },
  { id: "y2in3-062", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 62", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\frac{\\cos 2x}{\\cos x + \\sin x} \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["trig", "double-angle"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identities used.", workingLatex: "\\cos^{2}\\theta = \\frac{1 + \\cos 2\\theta}{2} \\\\\\\\[2pt] \\sin^{2}\\theta = \\frac{1 - \\cos 2\\theta}{2}", explanation: "Half-angle identity for cosine. Rearranges \\(\\cos 2\\theta = 2\\cos^2\\theta - 1\\).  Half-angle (power-reduction) identity. Rearranges \\(\\cos 2\\theta = 1 - 2\\sin^2\\theta\\) — the form that lets us integrate \\(\\sin^2\\), which has no elementary antiderivative on its own." }, { stepNumber: 2, description: "Factor \\(\\cos 2x\\) as a difference of squares.", workingLatex: "\\cos 2x = \\cos^2 x - \\sin^2 x = \\left(\\cos x - \\sin x\\right)\\left(\\cos x + \\sin x\\right)", explanation: "" }, { stepNumber: 3, description: "Cancel the common factor.", workingLatex: "\\frac{\\cos 2x}{\\cos x + \\sin x} = \\cos x - \\sin x", explanation: "" }, { stepNumber: 4, description: "Integrate.", workingLatex: "\\displaystyle\\int \\left(\\cos x - \\sin x\\right)\\,dx = \\sin x + \\cos x + C", explanation: "\\(\\int -\\sin x = +\\cos x\\) — the two minuses combine." } ], finalAnswer: "\\(\\sin x + \\cos x + C\\)." } },
  { id: "y2in3-063", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 63", difficulty: "Standard", questionText: "Find the area between \\(y = \\sin^2 x\\) and the x-axis on \\([0, \\pi]\\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["definite", "trig", "area"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\sin^{2}\\theta = \\frac{1 - \\cos 2\\theta}{2}", explanation: "Half-angle (power-reduction) identity. Rearranges \\(\\cos 2\\theta = 1 - 2\\sin^2\\theta\\) — the form that lets us integrate \\(\\sin^2\\), which has no elementary antiderivative on its own." }, { stepNumber: 2, description: "Set up the area as a definite integral.", workingLatex: "\\text{Area} = \\displaystyle\\int_0^{\\pi} \\sin^2 x\\,dx", explanation: "\\(\\sin^2 x \\ge 0\\), so the definite integral gives the unsigned area." }, { stepNumber: 3, description: "Find the antiderivative.", workingLatex: "\\displaystyle\\int \\sin^2 x\\,dx = \\frac{x}{2} - \\frac{\\sin 2x}{4}", explanation: "" }, { stepNumber: 4, description: "Apply the limits.", workingLatex: "\\left[\\frac{x}{2} - \\frac{\\sin 2x}{4}\\right]_0^{\\pi} = \\frac{\\pi}{2} - 0 = \\frac{\\pi}{2}", explanation: "" } ], finalAnswer: "\\(\\frac{\\pi}{2}\\)." } },
  { id: "y2in3-064", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 64", difficulty: "Standard", questionText: "Find the average value of \\(\\sin^2 x\\) on \\([0, 2\\pi]\\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["definite", "trig", "average"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identities used.", workingLatex: "\\bar f = \\frac{1}{b-a}\\displaystyle\\int_a^b f(x)\\,dx \\\\\\\\[2pt] \\sin^{2}\\theta = \\frac{1 - \\cos 2\\theta}{2}", explanation: "Average value of a function on \\([a, b]\\).  Half-angle (power-reduction) identity. Rearranges \\(\\cos 2\\theta = 1 - 2\\sin^2\\theta\\) — the form that lets us integrate \\(\\sin^2\\), which has no elementary antiderivative on its own." }, { stepNumber: 2, description: "Apply the average-value formula.", workingLatex: "\\bar f = \\frac{1}{2\\pi - 0}\\displaystyle\\int_0^{2\\pi} \\sin^2 x\\,dx = \\frac{1}{2\\pi}\\displaystyle\\int_0^{2\\pi} \\sin^2 x\\,dx", explanation: "" }, { stepNumber: 3, description: "Find the antiderivative.", workingLatex: "\\displaystyle\\int \\sin^2 x\\,dx = \\frac{x}{2} - \\frac{\\sin 2x}{4}", explanation: "" }, { stepNumber: 4, description: "Apply the limits.", workingLatex: "\\displaystyle\\int_0^{2\\pi} \\sin^2 x\\,dx = \\left[\\frac{x}{2} - \\frac{\\sin 2x}{4}\\right]_0^{2\\pi} = \\pi - 0 = \\pi", explanation: "\\(\\sin 4\\pi = 0\\)." }, { stepNumber: 5, description: "Divide.", workingLatex: "\\bar f = \\frac{\\pi}{2\\pi} = \\frac{1}{2}", explanation: "\\(\\sin^2 x\\) averages \\(1/2\\) over any whole number of periods — \\(\\sin^2 + \\cos^2 = 1\\) and the two have the same average, each \\(1/2\\)." } ], finalAnswer: "\\(\\frac{1}{2}\\)." } },
  { id: "y2in3-065", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 65", difficulty: "Challenge", questionText: "Find the volume of revolution of \\(y = \\sin x\\) about the x-axis on \\([0, \\pi]\\).", marks: 4, examStyle: false, yearCreated: 2026, tags: ["definite", "trig", "volume"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identities used.", workingLatex: "V = \\pi\\displaystyle\\int_a^b y^{2}\\,dx \\\\\\\\[2pt] \\sin^{2}\\theta = \\frac{1 - \\cos 2\\theta}{2}", explanation: "Volume of revolution about the x-axis: disc-method formula.  Half-angle (power-reduction) identity. Rearranges \\(\\cos 2\\theta = 1 - 2\\sin^2\\theta\\) — the form that lets us integrate \\(\\sin^2\\), which has no elementary antiderivative on its own." }, { stepNumber: 2, description: "Apply the disc-method formula.", workingLatex: "V = \\pi\\displaystyle\\int_0^{\\pi} y^2\\,dx = \\pi\\displaystyle\\int_0^{\\pi} \\sin^2 x\\,dx", explanation: "Each thin disc has area \\(\\pi y^2\\) and thickness \\(dx\\); summing gives \\(V\\)." }, { stepNumber: 3, description: "Find the antiderivative of \\(\\sin^2 x\\).", workingLatex: "\\displaystyle\\int \\sin^2 x\\,dx = \\frac{x}{2} - \\frac{\\sin 2x}{4}", explanation: "" }, { stepNumber: 4, description: "Apply the limits.", workingLatex: "\\displaystyle\\int_0^{\\pi} \\sin^2 x\\,dx = \\left[\\frac{x}{2} - \\frac{\\sin 2x}{4}\\right]_0^{\\pi} = \\frac{\\pi}{2}", explanation: "" }, { stepNumber: 5, description: "Multiply by \\(\\pi\\).", workingLatex: "V = \\pi \\cdot \\frac{\\pi}{2} = \\frac{\\pi^2}{2}", explanation: "" } ], finalAnswer: "\\(\\frac{\\pi^2}{2}\\)." } },
  { id: "y2in3-066", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 66", difficulty: "Challenge", questionText: "Find the volume of revolution of \\(y = \\cos x\\) about the x-axis on \\([0, \\pi/2]\\).", marks: 4, examStyle: false, yearCreated: 2026, tags: ["definite", "trig", "volume"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identities used.", workingLatex: "V = \\pi\\displaystyle\\int_a^b y^{2}\\,dx \\\\\\\\[2pt] \\cos^{2}\\theta = \\frac{1 + \\cos 2\\theta}{2}", explanation: "Volume of revolution about the x-axis: disc-method formula.  Half-angle identity for cosine. Rearranges \\(\\cos 2\\theta = 2\\cos^2\\theta - 1\\)." }, { stepNumber: 2, description: "Apply the disc-method formula.", workingLatex: "V = \\pi\\displaystyle\\int_0^{\\pi/2} \\cos^2 x\\,dx", explanation: "" }, { stepNumber: 3, description: "Find the antiderivative.", workingLatex: "\\displaystyle\\int \\cos^2 x\\,dx = \\frac{x}{2} + \\frac{\\sin 2x}{4}", explanation: "" }, { stepNumber: 4, description: "Apply the limits.", workingLatex: "\\displaystyle\\int_0^{\\pi/2} \\cos^2 x\\,dx = \\left[\\frac{x}{2} + \\frac{\\sin 2x}{4}\\right]_0^{\\pi/2} = \\frac{\\pi}{4}", explanation: "" }, { stepNumber: 5, description: "Multiply by \\(\\pi\\).", workingLatex: "V = \\pi \\cdot \\frac{\\pi}{4} = \\frac{\\pi^2}{4}", explanation: "" } ], finalAnswer: "\\(\\frac{\\pi^2}{4}\\)." } },
  { id: "y2in3-067", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 67", difficulty: "Foundation", questionText: "Evaluate \\( \\displaystyle\\int \\left(\\sin^2 x + \\cos^2 x\\right) \\,dx \\).", marks: 1, examStyle: false, yearCreated: 2026, tags: ["trig", "pythag"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\sin^{2}\\theta + \\cos^{2}\\theta = 1", explanation: "The Pythagorean identity. Used to split \\(\\sin^3 = \\sin\\left(1-\\cos^2\\right)\\) or \\(\\cos^3 = \\cos\\left(1-\\sin^2\\right)\\) into pieces that admit a substitution." }, { stepNumber: 2, description: "Apply the Pythagorean identity to simplify.", workingLatex: "\\sin^2 x + \\cos^2 x = 1", explanation: "The integrand simplifies to a constant — there is nothing trig left after applying the identity." }, { stepNumber: 3, description: "Integrate.", workingLatex: "\\displaystyle\\int 1\\,dx = x + C", explanation: "" } ], finalAnswer: "\\(x + C\\)." } },
  { id: "y2in3-068", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 68", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\left(2\\cos x\\right)^2 \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig", "half-angle"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\cos^{2}\\theta = \\frac{1 + \\cos 2\\theta}{2}", explanation: "Half-angle identity for cosine. Rearranges \\(\\cos 2\\theta = 2\\cos^2\\theta - 1\\)." }, { stepNumber: 2, description: "Expand the square.", workingLatex: "\\left(2\\cos x\\right)^2 = 4\\cos^2 x", explanation: "" }, { stepNumber: 3, description: "Apply the half-angle identity.", workingLatex: "4\\cos^2 x = 4 \\cdot \\frac{1 + \\cos 2x}{2} = 2\\left(1 + \\cos 2x\\right) = 2 + 2\\cos 2x", explanation: "" }, { stepNumber: 4, description: "Integrate.", workingLatex: "\\displaystyle\\int \\left(2 + 2\\cos 2x\\right)\\,dx = 2x + 2 \\cdot \\frac{\\sin 2x}{2} + C = 2x + \\sin 2x + C", explanation: "" } ], finalAnswer: "\\(2x + \\sin 2x + C\\)." } },
  { id: "y2in3-069", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 69", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\sec^2 x\\tan x \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["trig", "u-substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\text{If } u = g(x),\\;\\; du = g\\'(x)\\,dx \\;\\Rightarrow\\; \\displaystyle\\int f(g(x))\\,g\\'(x)\\,dx = \\displaystyle\\int f(u)\\,du", explanation: "Reverse-chain-rule (substitution). Used here whenever the integrand contains a function and its derivative as a factor — pick the inner part as \\(u\\)." }, { stepNumber: 2, description: "Spot the function-and-its-derivative pattern.", workingLatex: "\\frac{d}{dx}\\tan x = \\sec^2 x", explanation: "\\(\\tan x\\) appears as a factor; the other factor \\(\\sec^2 x\\) is exactly its derivative — canonical u-sub setup." }, { stepNumber: 3, description: "Substitute \\(u = \\tan x\\).", workingLatex: "u = \\tan x,\\;\\; du = \\sec^2 x\\,dx", explanation: "" }, { stepNumber: 4, description: "Convert the integral.", workingLatex: "\\displaystyle\\int \\sec^2 x\\tan x\\,dx = \\displaystyle\\int u\\,du", explanation: "" }, { stepNumber: 5, description: "Integrate.", workingLatex: "\\displaystyle\\int u\\,du = \\frac{u^2}{2} + C", explanation: "" }, { stepNumber: 6, description: "Back-substitute.", workingLatex: "= \\frac{\\tan^2 x}{2} + C", explanation: "" } ], finalAnswer: "\\(\\frac{\\tan^2 x}{2} + C\\)." } },
  { id: "y2in3-070", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 70", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\csc^2 x\\cot x \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["trig", "u-substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identity used.", workingLatex: "\\text{If } u = g(x),\\;\\; du = g\\'(x)\\,dx \\;\\Rightarrow\\; \\displaystyle\\int f(g(x))\\,g\\'(x)\\,dx = \\displaystyle\\int f(u)\\,du", explanation: "Reverse-chain-rule (substitution). Used here whenever the integrand contains a function and its derivative as a factor — pick the inner part as \\(u\\)." }, { stepNumber: 2, description: "Spot the function-and-its-derivative pattern.", workingLatex: "\\frac{d}{dx}\\cot x = -\\csc^2 x", explanation: "\\(\\cot x\\) appears as a factor; the other factor \\(\\csc^2 x\\) is the NEGATIVE derivative — substitution picks up a minus." }, { stepNumber: 3, description: "Substitute \\(u = \\cot x\\).", workingLatex: "u = \\cot x,\\;\\; du = -\\csc^2 x\\,dx \\;\\Rightarrow\\; \\csc^2 x\\,dx = -du", explanation: "" }, { stepNumber: 4, description: "Convert the integral.", workingLatex: "\\displaystyle\\int \\csc^2 x\\cot x\\,dx = \\displaystyle\\int u \\cdot \\left(-du\\right) = -\\displaystyle\\int u\\,du", explanation: "" }, { stepNumber: 5, description: "Integrate.", workingLatex: "-\\displaystyle\\int u\\,du = -\\frac{u^2}{2} + C", explanation: "" }, { stepNumber: 6, description: "Back-substitute.", workingLatex: "= -\\frac{\\cot^2 x}{2} + C", explanation: "" } ], finalAnswer: "\\(-\\frac{\\cot^2 x}{2} + C\\)." } },
  { id: "y2in3-071", topicRef: "y2in3", topicTitle: "Using Trigonometric Identities 71", difficulty: "Standard", questionText: "Find the average of \\(\\cos^2 x\\) on \\([0, 2\\pi]\\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["definite", "trig", "average"], workedSolution: { steps: [ { stepNumber: 1, description: "State the identities used.", workingLatex: "\\bar f = \\frac{1}{b-a}\\displaystyle\\int_a^b f(x)\\,dx \\\\\\\\[2pt] \\cos^{2}\\theta = \\frac{1 + \\cos 2\\theta}{2}", explanation: "Average value of a function on \\([a, b]\\).  Half-angle identity for cosine. Rearranges \\(\\cos 2\\theta = 2\\cos^2\\theta - 1\\)." }, { stepNumber: 2, description: "Apply the average-value formula.", workingLatex: "\\bar f = \\frac{1}{2\\pi}\\displaystyle\\int_0^{2\\pi} \\cos^2 x\\,dx", explanation: "" }, { stepNumber: 3, description: "Find the antiderivative.", workingLatex: "\\displaystyle\\int \\cos^2 x\\,dx = \\frac{x}{2} + \\frac{\\sin 2x}{4}", explanation: "" }, { stepNumber: 4, description: "Apply the limits.", workingLatex: "\\displaystyle\\int_0^{2\\pi} \\cos^2 x\\,dx = \\left[\\frac{x}{2} + \\frac{\\sin 2x}{4}\\right]_0^{2\\pi} = \\pi - 0 = \\pi", explanation: "" }, { stepNumber: 5, description: "Divide.", workingLatex: "\\bar f = \\frac{\\pi}{2\\pi} = \\frac{1}{2}", explanation: "Same as the \\(\\sin^2 x\\) average — by symmetry." } ], finalAnswer: "\\(\\frac{1}{2}\\)." } },
];
